// READ-ONLY. Times the REAL server-side functions (directory names only).
const now = () => Number(process.hrtime.bigint() / 1000n) / 1000;
async function t<T>(f: () => Promise<T>) { const a = now(); const r = await f(); return [now() - a, r] as const; }
async function main() {
  for (const id of process.argv.slice(2)) {
    const s: any = await db.server.findFirst({ where:{ id:{ endsWith:id } }, select:{ id:true,userId:true,status:true,rootPassword:true,rootPasswordEnc:true,sshManagementKeyEnc:true,sshPort:true,guestSshPort:true,dedicatedIp:{select:{address:true}},node:{select:{publicIp:true}} } });
    const pk = { poolKey: `u:${s.id}` };
    const before: number[] = [], after: number[] = [];
    for (let i = 0; i < 6; i++) before.push((await t(() => listDir(s, "/opt")))[0]);           // unpooled: handshake per call
    for (let i = 0; i < 6; i++) after.push((await t(() => listDir(s, "/opt", pk)))[0]);        // pooled: 1st pays the handshake
    const med = (a: number[]) => [...a].sort((x, y) => x - y)[Math.floor(a.length / 2)];
    // missing-folder fallback: old = sequential probes (one connection each); new = one call
    const missing = "/opt/definitely-not-there/a/b";
    const [tOld] = await t(async () => { let cur = missing; for (;;) { try { await listDir(s, cur); return; } catch { const up = cur.slice(0, cur.lastIndexOf("/")); cur = up || "/"; } } });
    const [tNew, r] = await t(() => listNearestDir(s, missing, pk));
    console.log(id.slice(-6), `unpooled median=${med(before).toFixed(0)}ms (all: ${before.map(x=>x.toFixed(0)).join("/")}) | pooled first=${after[0].toFixed(0)}ms, then median=${med(after.slice(1)).toFixed(0)}ms (${after.slice(1).map(x=>x.toFixed(0)).join("/")}) | missing-folder walk: old sequential=${tOld.toFixed(0)}ms new single-call=${tNew.toFixed(0)}ms -> ${r.path}`);
  }
  process.exit(0);
}
main();

