"use client";

import { useState, useTransition } from "react";
import { adminReviewTransfer, adminSetTransferFlag } from "@/lib/actions-region-transfer";

export function TransferFlag({ on }: { on: boolean }) {
  const [state, setState] = useState(on);
  const [pending, start] = useTransition();
  return (
    <div className="card flex items-start justify-between gap-4 p-4">
      <div>
        <h3 className="text-sm font-semibold">Customer region-transfer requests</h3>
        <p className="mt-1 text-xs text-slate-400">Shows the &ldquo;Move to another location&rdquo; card on customers&apos; game servers. It only creates a request here; nothing is moved. The move engine is still NO-GO for real customers until its rehearsals are done.</p>
      </div>
      <button type="button" role="switch" aria-checked={state} disabled={pending}
        onClick={() => start(async () => {
          const next = !state;
          if (next && !confirm("Show the transfer-request card to customers?")) return;
          const r = await adminSetTransferFlag(next);
          if (r.ok) setState(next);
        })}
        className={`relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors disabled:opacity-50 ${state ? "bg-brand-500" : "bg-white/[0.12]"}`}>
        <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-[#fff] shadow transition ${state ? "translate-x-5" : "translate-x-0"}`} />
      </button>
    </div>
  );
}

export function TransferActions({ id, status }: { id: string; status: string }) {
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const run = (a: "approve" | "reject" | "complete", note?: string) => start(async () => {
    const r = await adminReviewTransfer(id, a, note);
    setMsg(r.ok ? "Saved. Reload to see it." : r.error);
  });
  return (
    <div className="flex flex-wrap items-center gap-2">
      {status === "REQUESTED" && <button className="btn-primary py-1 text-xs" disabled={pending} onClick={() => run("approve")}>Approve (bookkeeping)</button>}
      {(status === "REQUESTED" || status === "APPROVED") && (
        <button className="btn-ghost py-1 text-xs text-red-300" disabled={pending}
          onClick={() => { const n = prompt("Reason shown to the customer (optional)"); if (n !== null) run("reject", n); }}>Decline</button>
      )}
      {status === "APPROVED" && <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => confirm("Mark as completed? Only after the move has really finished.") && run("complete")}>Mark completed</button>}
      {msg && <span className="text-xs text-slate-300">{msg}</span>}
    </div>
  );
}
