 * where NXEON_ENV=staging (set in /opt/nxeon-staging/.env, absent in
 * production) and is a plain 404 everywhere else, even after the code merges.
 * Everything visual is scoped under `.nxm` (see nxm.css) so it can never
 * reach the portal, admin or the live marketing pages.
 */
// No `title` here: a plain title in this layout would reset the root layout's
// "%s — Nxeon" template for every page below it. Each page sets its own SEO
// (app/nxm/_seo).
export const metadata: Metadata = {
  robots: process.env.NXM_LIVE === "1" ? { index: true, follow: true } : { index: false, follow: false, nocache: true },
