/**
 * Dedicated-server catalogue: fetch + parse the upstream bare-metal public
 * catalogue. ADMIN-ONLY MODULE — the vendor's names, plan codes and URLs live
 * here and in the admin pages only. Nothing customer-facing may import this
 * file (test/dedicated-brand-voice.test.ts enforces it); customer surfaces read
 * the brand-safe projections in lib/dedicated/customer-view.ts.
 *
 * Endpoints (verified live 2026-10-06, all anonymous GETs, no API keys):
 *   GET {api}/order/catalog/public/eco?ovhSubsidiary=XX               Kimsufi / So you Start / Rise / Advance (eco ranges)
 *   GET {api}/order/catalog/public/baremetalServers?ovhSubsidiary=XX  Advance / Game / Scale / High Grade
 *   GET {api}/dedicated/server/datacenter/availabilities              real-time stock per plan+memory+storage per datacenter
 * where {api} is the API host that serves the subsidiary (US -> api.us.ovhcloud.com,
 * CA/ASIA/WE/WS/SG/AU/IN/QC -> ca.api.ovh.com, the EU subsidiaries -> eu.api.ovh.com).
 *
 * READ-ONLY by construction: `publicGet` only ever issues GET, never sends
 * credentials, and refuses any path outside the three read endpoints above.
 *
 * Prices in the catalogue are integers in 1e-8 of the currency unit
 * ("price": 10700000000 => $107.00), so cents = price / 1e6.
 */

export type CatalogKind = "eco" | "baremetalServers";
export const CATALOG_KINDS: readonly CatalogKind[] = ["eco", "baremetalServers"] as const;

/** Subsidiaries served by each API host (OVH's own split). */
const HOST_BY_SUBSIDIARY: Record<string, string> = {
  US: "https://api.us.ovhcloud.com/1.0",
  CA: "https://ca.api.ovh.com/1.0",
  QC: "https://ca.api.ovh.com/1.0",
  ASIA: "https://ca.api.ovh.com/1.0",
  AU: "https://ca.api.ovh.com/1.0",
  IN: "https://ca.api.ovh.com/1.0",
  SG: "https://ca.api.ovh.com/1.0",
  WE: "https://ca.api.ovh.com/1.0",
  WS: "https://ca.api.ovh.com/1.0",
};
const EU_HOST = "https://eu.api.ovh.com/1.0";

export const KNOWN_SUBSIDIARIES = ["WE", "WS", "ASIA", "CA", "QC", "SG", "AU", "IN", "US", "FR", "GB", "DE", "ES", "IT", "NL", "PL", "PT", "IE", "CZ", "FI", "LT", "MA", "SN", "TN"] as const;

export function isValidSubsidiary(s: string): boolean {
  return (KNOWN_SUBSIDIARIES as readonly string[]).includes(s);
}

export function apiHostFor(subsidiary: string): string {
  return HOST_BY_SUBSIDIARY[subsidiary] ?? EU_HOST;
}

export function catalogUrl(kind: CatalogKind, subsidiary: string): string {
  return `${apiHostFor(subsidiary)}/order/catalog/public/${kind}?ovhSubsidiary=${encodeURIComponent(subsidiary)}`;
}

export function availabilityUrl(subsidiary: string): string {
  return `${apiHostFor(subsidiary)}/dedicated/server/datacenter/availabilities`;
}

const ALLOWED_PATH = /^\/1\.0\/(order\/catalog\/public\/(eco|baremetalServers)|dedicated\/server\/datacenter\/availabilities)$/;

/** GET-only, credential-free fetch of one of the three public read endpoints. */
export async function publicGet(url: string, timeoutMs = 90_000): Promise<unknown> {
  const u = new URL(url);
  if (u.protocol !== "https:" || !ALLOWED_PATH.test(u.pathname)) {
    throw new Error(`refusing non-catalogue URL: ${u.pathname}`);
  }
  const res = await fetch(u, { method: "GET", headers: { accept: "application/json" }, signal: AbortSignal.timeout(timeoutMs), cache: "no-store" });
  if (!res.ok) throw new Error(`GET ${u.pathname} -> HTTP ${res.status}`);
  return res.json();
}

/* ------------------------------------------------------------------ *
 * Parsed (normalised) shapes
 * ------------------------------------------------------------------ */

export type OptionFamily = "memory" | "storage" | "system-storage" | "bandwidth" | "vrack" | "gpu";
export const OPTION_FAMILIES: readonly OptionFamily[] = ["memory", "storage", "system-storage", "bandwidth", "vrack", "gpu"] as const;

export type ParsedOption = {
  family: OptionFamily;
  planCode: string;
  productCode: string;
  label: string;
  isDefault: boolean;
  mandatory: boolean;
  /** Extra monthly cost on top of the base plan (0 for the included choice). */
  monthlyCents: number;
  setupCents: number;
  ramGb: number | null;
  storageGb: number | null;
  bandwidthMbps: number | null;
  /** Traffic cap in TB; 0 = unmetered; null = not a traffic option. */
  trafficTb: number | null;
  spec: Record<string, unknown>;
};

export type PricingTerm = {
  /** default | upfront12 | upfront24 | ... */
  mode: string;
  months: number;
  /** Price for the whole term (renew capacity). */
  termCents: number;
  setupCents: number;
};

export type ParsedPromotion = { name: string; description: string; endDate: string | null; appliesTo: "setup" | "renew" };

export type ParsedItem = {
  catalog: CatalogKind;
  planCode: string;
  productCode: string;
  range: string;
  name: string;
  invoiceName: string;
  cpuBrand: string;
  cpuModel: string;
  cpuCount: number;
  cpuCores: number;
  cpuThreads: number;
  cpuFrequencyGhz: number | null;
  cpuBoostGhz: number | null;
  datacenters: string[];
  currency: string;
  monthlyCents: number;
  setupCents: number;
  /** Setup after any live promotion (e.g. "free setup"), null when no promo. */
  promoSetupCents: number | null;
  terms: PricingTerm[];
  promotions: ParsedPromotion[];
  releaseYear: number | null;
  slaPercent: number | null;
  antiDdos: string | null;
  defaultRamGb: number | null;
  defaultStorage: string | null;
  defaultBandwidthMbps: number | null;
  options: ParsedOption[];
  spec: Record<string, unknown>;
};

export type ParseResult = {
  catalog: CatalogKind;
  subsidiary: string;
  currency: string;
  items: ParsedItem[];
  warnings: string[];
};

export type ParsedAvailability = {
  planCode: string;
  fqn: string;
  memory: string | null;
  storage: string | null;
  systemStorage: string | null;
  datacenter: string;
  availability: string;
};

/* ------------------------------------------------------------------ *
 * Helpers (tolerant: the upstream shape drifts, so every read is guarded)
 * ------------------------------------------------------------------ */

type Obj = Record<string, unknown>;
const isObj = (v: unknown): v is Obj => typeof v === "object" && v !== null && !Array.isArray(v);
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const str = (v: unknown): string => (typeof v === "string" ? v : "");
const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);
const get = (o: unknown, ...path: string[]): unknown => {
  let cur: unknown = o;
  for (const k of path) {
    if (!isObj(cur)) return undefined;
    cur = cur[k];
  }
  return cur;
};

/** Upstream price unit (1e-8 of the currency) -> integer cents. */
export function priceToCents(p: unknown): number {
  const n = num(p);
  return n == null ? 0 : Math.round(n / 1e6);
}

function pricingsOf(o: unknown): Obj[] {
  return arr(get(o, "pricings")).filter(isObj);
}

/** Monthly renew price + setup for the no-commitment ("default") mode. */
function monthlyAndSetup(o: unknown): { monthly: number | null; setup: number; promoSetup: number | null; promos: ParsedPromotion[] } {
  const ps = pricingsOf(o);
  const capsOf = (x: Obj) => arr(x.capacities).map(str);
  const monthlyRow = ps.find((x) => str(x.mode) === "default" && num(x.interval) === 1 && str(x.intervalUnit) === "month" && capsOf(x).includes("renew"));
  const setupRow = ps.find((x) => str(x.mode) === "default" && capsOf(x).includes("installation"));
  const promos: ParsedPromotion[] = [];
  let promoSetup: number | null = null;
  for (const [row, appliesTo] of [[setupRow, "setup"], [monthlyRow, "renew"]] as const) {
    for (const p of arr(row?.promotions).filter(isObj)) {
      promos.push({ name: str(p.name), description: str(p.description), endDate: str(p.endDate) || null, appliesTo });
      if (appliesTo === "setup") {
        const total = num(get(p, "total", "value"));
        if (total != null) promoSetup = Math.round(total / 1e6);
      }
    }
  }
  return { monthly: monthlyRow ? priceToCents(monthlyRow.price) : null, setup: setupRow ? priceToCents(setupRow.price) : 0, promoSetup, promos };
}

function termsOf(o: unknown): PricingTerm[] {
  const ps = pricingsOf(o);
  const modes = Array.from(new Set(ps.map((x) => str(x.mode)).filter(Boolean)));
  const out: PricingTerm[] = [];
  for (const mode of modes) {
    const renew = ps.find((x) => str(x.mode) === mode && arr(x.capacities).map(str).includes("renew") && (num(x.interval) ?? 0) > 0);
    if (!renew) continue;
    const setup = ps.find((x) => str(x.mode) === mode && arr(x.capacities).map(str).includes("installation"));
    out.push({ mode, months: num(renew.interval) ?? 1, termCents: priceToCents(renew.price), setupCents: setup ? priceToCents(setup.price) : 0 });
  }
  return out.sort((a, b) => a.months - b.months);
}

function storageSummary(tech: unknown): { label: string; gb: number } | null {
  const disks = arr(get(tech, "storage", "disks")).filter(isObj);
  if (disks.length === 0) return null;
  let gb = 0;
  const parts = disks.map((d) => {
    const n = num(d.number) ?? 1;
    const cap = num(d.capacity) ?? 0;
    gb += n * cap;
    const iface = str(d.interface) || str(d.technology);
    const capLabel = cap >= 1000 ? `${+(cap / 1000).toFixed(2)}TB` : `${cap}GB`;
    return `${n}x ${capLabel} ${iface}`.trim();
  });
  const raid = str(get(tech, "storage", "raid"));
  return { label: parts.join(" + ") + (raid ? ` (${raid})` : ""), gb };
}

/** Which plan addon-family names map onto our option families. */
function familyOf(name: string): OptionFamily | null {
  if (name === "memory") return "memory";
  if (name === "storage") return "storage";
  if (name === "system-storage") return "system-storage";
  if (name === "bandwidth" || name === "traffic" || name === "public-bandwidth") return "bandwidth";
  if (name === "vrack" || name === "private-bandwidth") return "vrack";
  if (name === "gpu") return "gpu";
  return null; // licences (windows/sql/cpanel/plesk) are not resold here
}

/** Best-effort range when the product blob does not say (older/odd entries). */
export function guessRange(planCode: string, invoiceName: string): string {
  const s = `${planCode} ${invoiceName}`.toLowerCase();
  if (/\bks-|sk\d|kimsufi/.test(s)) return "kimsufi";
  if (/\bsys-|sys\d|soyoustart/.test(s)) return "soyoustart";
  if (/rise/.test(s)) return "rise";
  if (/adv|advance/.test(s)) return "advance";
  if (/game/.test(s)) return "game";
  if (/scale|\bsc/.test(s)) return "scale";
  if (/hgr|hci|sds|sap|stor/.test(s)) return "hgr";
  return "other";
}

/* ------------------------------------------------------------------ *
 * Catalogue parser
 * ------------------------------------------------------------------ */

export function parseCatalog(raw: unknown, catalog: CatalogKind): ParseResult {
  const warnings: string[] = [];
  if (!isObj(raw) || !Array.isArray(raw.plans)) {
    throw new Error(`catalogue ${catalog}: response has no plans[] (shape changed?)`);
  }
  const subsidiary = str(get(raw, "locale", "subsidiary"));
  const currency = str(get(raw, "locale", "currencyCode")) || "USD";
  const products = new Map<string, Obj>();
  for (const p of arr(raw.products).filter(isObj)) products.set(str(p.name), p);
  const addons = new Map<string, Obj>();
  for (const a of arr(raw.addons).filter(isObj)) addons.set(str(a.planCode), a);

  const items: ParsedItem[] = [];
  for (const plan of arr(raw.plans).filter(isObj)) {
    const planCode = str(plan.planCode);
    if (!planCode) continue;
    try {
      const productCode = str(plan.product);
      const product = products.get(productCode);
      const tech = get(product, "blobs", "technical");
      const server = get(tech, "server");
      if (!isObj(server)) {
        warnings.push(`${planCode}: no server spec, skipped`);
        continue;
      }
      const invoiceName = str(plan.invoiceName);
      const commercialName = str(get(plan, "blobs", "commercial", "name"));
      const name = commercialName || invoiceName.split("|")[0].trim() || planCode;
      const range = (str(server.range) || guessRange(planCode, invoiceName)).toLowerCase();
      const cpu = get(server, "cpu");
      const configs = arr(plan.configurations).filter(isObj);
      const dcConf = configs.find((c) => str(c.name) === "dedicated_datacenter");
      const datacenters = arr(dcConf?.values).map(str).filter(Boolean);
      const { monthly, setup, promoSetup, promos } = monthlyAndSetup(plan);
      if (monthly == null) {
        warnings.push(`${planCode}: no monthly price, skipped`);
        continue;
      }
      const features = arr(get(plan, "blobs", "commercial", "features")).filter(isObj);
      const year = Number(str(features.find((f) => str(f.name) === "release-year")?.value));

      const options: ParsedOption[] = [];
      let defaultRamGb: number | null = null;
      let defaultStorage: string | null = null;
      let defaultBandwidthMbps: number | null = null;
      for (const fam of arr(plan.addonFamilies).filter(isObj)) {
        const family = familyOf(str(fam.name));
        if (!family) continue;
        const def = str(fam.default);
        const mandatory = fam.mandatory === true;
        for (const code of arr(fam.addons).map(str)) {
          const addon = addons.get(code);
          if (!addon) {
            warnings.push(`${planCode}: addon ${code} missing from catalogue`);
            continue;
          }
          const aprod = products.get(str(addon.product));
          const atech = get(aprod, "blobs", "technical");
          const { monthly: am, setup: as } = monthlyAndSetup(addon);
          const ramGb = num(get(atech, "memory", "size"));
          const st = storageSummary(atech);
          const bwLevel = num(get(atech, "bandwidth", "level")) ?? num(get(atech, "vrack", "level"));
          const limit = num(get(atech, "bandwidth", "limit"));
          const gpu = get(atech, "gpu");
          const label =
            family === "memory" && ramGb != null
              ? `${ramGb} GB ${str(get(atech, "memory", "ramType"))}${num(get(atech, "memory", "frequency")) ? ` ${num(get(atech, "memory", "frequency"))} MHz` : ""}`.trim()
              : family === "storage" || family === "system-storage"
                ? st?.label ?? str(aprod?.description) ?? code
                : family === "gpu" && isObj(gpu)
                  ? `${num(gpu.number) ?? 1}x ${str(gpu.brand)} ${str(gpu.model)}`.trim()
                  : str(aprod?.description) || str(addon.invoiceName) || code;
          const opt: ParsedOption = {
            family,
            planCode: code,
            productCode: str(addon.product),
            label,
            isDefault: code === def,
            mandatory,
            monthlyCents: am ?? 0,
            setupCents: as,
            ramGb,
            storageGb: st?.gb ?? null,
            bandwidthMbps: family === "bandwidth" || family === "vrack" ? bwLevel : null,
            trafficTb: family === "bandwidth" ? (limit ?? 0) : null,
            spec: isObj(atech) ? atech : {},
          };
          options.push(opt);
          if (opt.isDefault) {
            if (family === "memory") defaultRamGb = ramGb;
            if (family === "storage") defaultStorage = opt.label;
            if (family === "bandwidth") defaultBandwidthMbps = bwLevel;
          }
        }
      }

      items.push({
        catalog,
        planCode,
        productCode,
        range,
        name,
        invoiceName,
        cpuBrand: str(get(cpu, "brand")),
        cpuModel: str(get(cpu, "model")) || str(product?.description),
        cpuCount: num(get(cpu, "number")) ?? 1,
        cpuCores: num(get(cpu, "cores")) ?? 0,
        cpuThreads: num(get(cpu, "threads")) ?? 0,
        cpuFrequencyGhz: num(get(cpu, "frequency")),
        cpuBoostGhz: num(get(cpu, "boost")),
        datacenters,
        currency,
        monthlyCents: monthly,
        setupCents: setup,
        promoSetupCents: promoSetup,
        terms: termsOf(plan),
        promotions: promos,
        releaseYear: Number.isFinite(year) && year > 2000 ? year : null,
        slaPercent: num(get(server, "services", "sla")),
        antiDdos: str(get(server, "services", "antiddos")) || null,
        defaultRamGb,
        defaultStorage,
        defaultBandwidthMbps,
        options,
        spec: { server, osCount: arr(get(tech, "os", "features")).length },
      });
    } catch (e) {
      warnings.push(`${planCode}: parse error ${(e as Error).message}`);
    }
  }
  return { catalog, subsidiary, currency, items, warnings };
}

/* ------------------------------------------------------------------ *
 * Availability parser
 * ------------------------------------------------------------------ */

export function parseAvailability(raw: unknown, onlyPlans?: Set<string>): ParsedAvailability[] {
  if (!Array.isArray(raw)) throw new Error("availability: response is not an array (shape changed?)");
  const out: ParsedAvailability[] = [];
  for (const row of raw) {
    if (!isObj(row)) continue;
    const planCode = str(row.planCode);
    if (!planCode || (onlyPlans && !onlyPlans.has(planCode))) continue;
    const fqn = str(row.fqn) || planCode;
    for (const dc of arr(row.datacenters).filter(isObj)) {
      const datacenter = str(dc.datacenter);
      if (!datacenter) continue;
      out.push({
        planCode,
        fqn,
        memory: str(row.memory) || null,
        storage: str(row.storage) || null,
        systemStorage: str(row.systemStorage) || null,
        datacenter,
        availability: str(dc.availability) || "unknown",
      });
    }
  }
  return out;
}

/**
 * Upstream stock codes: "1H-high" / "1H-low" (deliverable within ~1h), "24H",
 * "72H", "240H", "480H" (lead time), "comingSoon", "unavailable", "unknown".
 */
export function isInStock(code: string): boolean {
  return /^\d+H/.test(code);
}

/** Lower is better; used to pick the best stock state across configurations. */
export function stockRank(code: string): number {
  const m = /^(\d+)H(-high|-low)?/.exec(code);
  if (m) return Number(m[1]) * 10 + (m[2] === "-low" ? 1 : 0);
  if (code === "comingSoon") return 100_000;
  if (code === "unknown") return 200_000;
  return 300_000; // unavailable / anything new
}

/** Admin-facing description of a stock code. */
export function stockLabel(code: string): string {
  const m = /^(\d+)H(-high|-low)?/.exec(code);
  if (m) {
    const h = Number(m[1]);
    const lead = h <= 1 ? "within 1 hour" : h < 48 ? `within ${h} hours` : `within ${Math.round(h / 24)} days`;
    return m[2] === "-low" ? `${lead} (low stock)` : lead;
  }
  if (code === "comingSoon") return "coming soon";
  if (code === "unavailable") return "out of stock";
  return "unknown";
}

