/**
 * Upstream datacenter codes (as the bare-metal catalogue and availability feed
 * spell them) -> Nxeon region codes, in the same "<3-letter city><n>" style as
 * lib/node-regions.ts. The upstream code is ADMIN-ONLY; customers only ever see
 * `customerLabel` (a country/metro name in Nxeon's voice).
 *
 * `sold` = Nxeon already operates in that metro (a Node lives there today, so
 * the region already exists in lib/node-regions.ts). The owner still decides
 * which regions dedicated servers are actually OFFERED in — that is the
 * `dedicated_enabled_regions` setting (lib/dedicated/pricing.ts), which
 * defaults to the sold ones.
 *
 * An upstream code that is missing from this table never throws: it maps to
 * `unmapped:<code>` and is flagged in the admin catalogue so the table can be
 * extended (the feed grows new metros over time, e.g. the Paris 3-AZ codes).
 */

export type DedicatedRegion = {
  /** Nxeon region code. */
  code: string;
  /** Admin label (precise city). */
  label: string;
  /** Customer label (what the public page and dashboard show). */
  customerLabel: string;
  /** ISO2 country for a flag. */
  country: string;
  /** Continent group for the public page's region filter. */
  area: "Americas" | "Europe" | "Asia-Pacific";
  /** Nxeon already runs infrastructure in this metro. */
  sold: boolean;
};

export const DEDICATED_DC_REGIONS: Record<string, DedicatedRegion> = {
  sgp: { code: "sgp1", label: "Singapore", customerLabel: "Singapore", country: "sg", area: "Asia-Pacific", sold: true },
  bhs: { code: "bhs1", label: "Beauharnois, CA", customerLabel: "Canada (Montreal)", country: "ca", area: "Americas", sold: true },
  gra: { code: "gra1", label: "Gravelines, FR", customerLabel: "France (North)", country: "fr", area: "Europe", sold: false },
  rbx: { code: "rbx1", label: "Roubaix, FR", customerLabel: "France (North)", country: "fr", area: "Europe", sold: false },
  sbg: { code: "sbg1", label: "Strasbourg, FR", customerLabel: "France (East)", country: "fr", area: "Europe", sold: false },
  waw: { code: "waw1", label: "Warsaw, PL", customerLabel: "Poland", country: "pl", area: "Europe", sold: false },
  fra: { code: "fra1", label: "Frankfurt, DE", customerLabel: "Germany (Frankfurt)", country: "de", area: "Europe", sold: false },
  lon: { code: "lon1", label: "London, UK", customerLabel: "United Kingdom", country: "gb", area: "Europe", sold: false },
  syd: { code: "syd1", label: "Sydney, AU", customerLabel: "Australia", country: "au", area: "Asia-Pacific", sold: false },
  ynm: { code: "bom1", label: "Mumbai, IN", customerLabel: "India (Mumbai)", country: "in", area: "Asia-Pacific", sold: false },
  vin: { code: "vin1", label: "Vint Hill, US-East", customerLabel: "United States (East)", country: "us", area: "Americas", sold: false },
  hil: { code: "hil1", label: "Hillsboro, US-West", customerLabel: "United States (West)", country: "us", area: "Americas", sold: false },
  "ca-east-tor-a": { code: "tor1", label: "Toronto, CA", customerLabel: "Canada (Toronto)", country: "ca", area: "Americas", sold: false },
  "eu-west-par-a": { code: "par1", label: "Paris, FR (zone A)", customerLabel: "France (Paris)", country: "fr", area: "Europe", sold: false },
  "eu-west-par-b": { code: "par2", label: "Paris, FR (zone B)", customerLabel: "France (Paris)", country: "fr", area: "Europe", sold: false },
  "eu-west-par-c": { code: "par3", label: "Paris, FR (zone C)", customerLabel: "France (Paris)", country: "fr", area: "Europe", sold: false },
};

export function regionForDc(dc: string): DedicatedRegion {
  return (
    DEDICATED_DC_REGIONS[dc] ?? {
      code: `unmapped:${dc}`,
      label: `Unmapped (${dc})`,
      customerLabel: "Other location",
      country: "",
      area: "Europe",
      sold: false,
    }
  );
}

export function isMappedDc(dc: string): boolean {
  return dc in DEDICATED_DC_REGIONS;
}

/** Every Nxeon region code reachable from the table (deduplicated, table order). */
export function allDedicatedRegionCodes(): string[] {
  return Array.from(new Set(Object.values(DEDICATED_DC_REGIONS).map((r) => r.code)));
}

/** Reverse lookup: Nxeon region code -> the region record (first match). */
export function regionByCode(code: string): DedicatedRegion | null {
  return Object.values(DEDICATED_DC_REGIONS).find((r) => r.code === code) ?? null;
}

/** Customer label for a Nxeon region code — never the upstream code. */
export function customerDedicatedRegionLabel(code: string): string {
  return regionByCode(code)?.customerLabel ?? "Other location";
}

/** Upstream dc codes that map to a given Nxeon region code. */
export function dcsForRegion(code: string): string[] {
  return Object.entries(DEDICATED_DC_REGIONS)
    .filter(([, r]) => r.code === code)
    .map(([dc]) => dc);
}

