      customerLabel: "Other location",
      country: "",
      area: "Europe",
      sold: false,
    }
  );
}

export function isMappedDc(dc: string): boolean {
  return dc in DEDICATED_DC_REGIONS;
}

/** Every Nxeon region code reachable from the table (deduplicated, table order). */
export function allDedicatedRegionCodes(): string[] {
  return Array.from(new Set(Object.values(DEDICATED_DC_REGIONS).map((r) => r.code)));
}

/** Reverse lookup: Nxeon region code -> the region record (first match). */
export function regionByCode(code: string): DedicatedRegion | null {
  return Object.values(DEDICATED_DC_REGIONS).find((r) => r.code === code) ?? null;
}

/** Customer label for a Nxeon region code — never the upstream code. */
export function customerDedicatedRegionLabel(code: string): string {
  return regionByCode(code)?.customerLabel ?? "Other location";
}

/** Upstream dc codes that map to a given Nxeon region code. */
export function dcsForRegion(code: string): string[] {
  return Object.entries(DEDICATED_DC_REGIONS)
    .filter(([, r]) => r.code === code)
    .map(([dc]) => dc);
}

