input.content:
/**
 * Dedicated catalogue sync — mirrors the upstream public bare-metal catalogue
 * + stock feed into DedicatedCatalogItem / Option / Availability.
 *
 * RESILIENCE (keep last good):
 *   - each catalogue (eco, baremetalServers) is fetched + parsed independently;
 *     one failing leaves that catalogue's rows exactly as they were (PARTIAL);
 *   - a parse that returns far fewer plans than we already hold (<30% of a
 *     catalogue of >10) is treated as an upstream glitch, NOT as mass removal;
 *   - the stock snapshot is replaced in one transaction only when the new feed
 *     parsed and is not suspiciously small; otherwise the old one stays;
 *   - every attempt is logged to DedicatedCatalogSync (status, counts, warnings).
 * Nxeon-owned columns (visible, markup, overrides, notes...) are never written here.
 *
 * READ-ONLY upstream: only lib/dedicated/ovh-catalog.ts `publicGet` (GET, no auth).
 */
import { createHash } from "node:crypto";
import { db } from "../db";
import { getSetting, setSetting } from "../settings";
import {
  CATALOG_KINDS,
  apiHostFor,
  availabilityUrl,
  catalogUrl,
  isValidSubsidiary,
  parseAvailability,
  parseCatalog,
  publicGet,
  type CatalogKind,
  type ParseResult,
  type ParsedItem,
} from "./ovh-catalog";
import { isMappedDc } from "./regions";

export type Fetcher = (url: string) => Promise<unknown>;

/** "ca" | "eu" | "us" — the availability feed is per API host, not per subsidiary. */
export function feedFor(subsidiary: string): string {
  const h = apiHostFor(subsidiary);
  return h.includes("api.us.") ? "us" : h.includes("ca.api.") ? "ca" : "eu";
}

/** Pure: is a fresh result plausible enough to replace what we hold? */
export function plausibleReplacement(newCount: number, currentCount: number): boolean {
  if (newCount <= 0) return false;
  if (currentCount <= 10) return true;
  return newCount >= currentCount * 0.3;
}

/** Pure: should the worker run a sync now? */
export function syncDue(args: { enabled: boolean; lastStartedAt: Date | null; intervalHours: number; requested: boolean; now: Date }): boolean {
  if (args.requested) return true;
  if (!args.enabled) return false;
  if (!args.lastStartedAt) return true;
  const h = Number.isFinite(args.intervalHours) && args.intervalHours > 0 ? args.intervalHours : 6;
  return args.now.getTime() - args.lastStartedAt.getTime() >= h * 3_600_000;
}

export function itemHash(it: ParsedItem): string {
  return createHash("sha256").update(JSON.stringify(it)).digest("hex");
}

/** Pure summary used for the sync log + the admin panel. */
export function summarise(results: ParseResult[]): {
  catalogs: Record<string, { plans: number; ranges: Record<string, number>; datacenters: Record<string, number> }>;
  unmappedDcs: string[];
  totalPlans: number;
} {
  const catalogs: Record<string, { plans: number; ranges: Record<string, number>; datacenters: Record<string, number> }> = {};
  const unmapped = new Set<string>();
  let total = 0;
  for (const r of results) {
    const c = { plans: r.items.length, ranges: {} as Record<string, number>, datacenters: {} as Record<string, number> };
    for (const it of r.items) {
      c.ranges[it.range] = (c.ranges[it.range] ?? 0) + 1;
      for (const dc of it.datacenters) {
        c.datacenters[dc] = (c.datacenters[dc] ?? 0) + 1;
        if (!isMappedDc(dc)) unmapped.add(dc);
      }
    }
    catalogs[r.catalog] = c;
    total += r.items.length;
  }
  return { catalogs, unmappedDcs: [...unmapped].sort(), totalPlans: total };
}

const upstreamData = (it: ParsedItem, subsidiary: string, hash: string) => ({
  subsidiary,
  catalog: it.catalog,
  planCode: it.planCode,
  productCode: it.productCode,
  range: it.range,
  name: it.name,
  invoiceName: it.invoiceName,
  cpuBrand: it.cpuBrand,
  cpuModel: it.cpuModel,
  cpuCount: it.cpuCount,
  cpuCores: it.cpuCores,
  cpuThreads: it.cpuThreads,
  cpuFrequencyGhz: it.cpuFrequencyGhz,
  cpuBoostGhz: it.cpuBoostGhz,
  defaultRamGb: it.defaultRamGb,
  defaultStorage: it.defaultStorage,
  defaultBandwidthMbps: it.defaultBandwidthMbps,
  datacenters: it.datacenters,
  currency: it.currency,
  monthlyCents: it.monthlyCents,
  setupCents: it.setupCents,
  promoSetupCents: it.promoSetupCents,
  terms: it.terms as unknown as object,
  promotions: it.promotions as unknown as object,
  releaseYear: it.releaseYear,
  slaPercent: it.slaPercent,
  antiDdos: it.antiDdos,
  spec: it.spec as object,
  hash,
});

export type SyncOutcome = {
  syncId: string;
  status: "OK" | "PARTIAL" | "FAILED";
  plansSeen: number;
  added: number;
  changed: number;
  removed: number;
  priceChanges: number;
  availabilityRows: number;
  warnings: string[];
  error: string | null;
};

let inFlight: Promise<SyncOutcome> | null = null;

/** Run one sync. Concurrent callers in the same process share the in-flight run. */
export function runCatalogSync(opts: { trigger: "worker" | "admin" | "script"; requestedById?: string | null; subsidiary?: string; fetcher?: Fetcher } = { trigger: "script" }): Promise<SyncOutcome> {
  if (inFlight) return inFlight;
  inFlight = doSync(opts).finally(() => {
    inFlight = null;
  });
  return inFlight;
}

async function doSync(opts: { trigger: string; requestedById?: string | null; subsidiary?: string; fetcher?: Fetcher }): Promise<SyncOutcome> {
  const t0 = Date.now();
  const subsidiary = (opts.subsidiary ?? (await getSetting("dedicated_catalog_subsidiary", "WE"))).trim().toUpperCase();
  const fetcher: Fetcher = opts.fetcher ?? ((u) => publicGet(u));
  const sync = await db.dedicatedCatalogSync.create({ data: { trigger: opts.trigger, subsidiary, requestedById: opts.requestedById ?? null } });
  const warnings: string[] = [];
  const errors: string[] = [];
  let added = 0, changed = 0, removed = 0, priceChanges = 0, optionsSeen = 0, availabilityRows = 0;
  const parsed: ParseResult[] = [];

  try {
    if (!isValidSubsidiary(subsidiary)) throw new Error(`unknown subsidiary "${subsidiary}"`);

    for (const kind of CATALOG_KINDS) {
      let res: ParseResult;
      try {
        res = parseCatalog(await fetcher(catalogUrl(kind, subsidiary)), kind);
      } catch (e) {
        errors.push(`${kind}: ${(e as Error).message} (kept last good)`);
        continue;
      }
      warnings.push(...res.warnings.slice(0, 50).map((w) => `${kind}: ${w}`));
      if (res.currency !== "USD") warnings.push(`${kind}: catalogue currency is ${res.currency}, Nxeon bills USD — prices are NOT converted`);
      const current = await db.dedicatedCatalogItem.count({ where: { subsidiary, catalog: kind, removedAt: null } });
      if (!plausibleReplacement(res.items.length, current)) {
        errors.push(`${kind}: only ${res.items.length} plans parsed vs ${current} held — looks like an upstream glitch, kept last good`);
        continue;
      }
      parsed.push(res);
      const r = await applyCatalog(subsidiary, kind, res.items);
      added += r.added; changed += r.changed; removed += r.removed; priceChanges += r.priceChanges; optionsSeen += r.optionsSeen;
    }

    // Stock feed (one per API host). Only plans we actually hold.
    try {
      const feed = feedFor(subsidiary);
      const plans = new Set((await db.dedicatedCatalogItem.findMany({ where: { subsidiary }, select: { planCode: true } })).map((p) => p.planCode));
      const rows = parseAvailability(await fetcher(availabilityUrl(subsidiary)), plans);
      const current = await db.dedicatedAvailability.count({ where: { feed } });
      if (!plausibleReplacement(rows.length, current)) {
        errors.push(`availability: only ${rows.length} rows vs ${current} held, kept last good`);
      } else {
        const fetchedAt = new Date();
        await db.$transaction(async (tx) => {
          await tx.dedicatedAvailability.deleteMany({ where: { feed } });
          for (let i = 0; i < rows.length; i += 5000) {
            await tx.dedicatedAvailability.createMany({ data: rows.slice(i, i + 5000).map((r) => ({ ...r, feed, fetchedAt })), skipDuplicates: true });
          }
        }, { timeout: 120_000 });
        availabilityRows = rows.length;
      }
    } catch (e) {
      errors.push(`availability: ${(e as Error).message} (kept last good)`);
    }
  } catch (e) {
    errors.push((e as Error).message);
  }

  const status: SyncOutcome["status"] = parsed.length === 0 ? "FAILED" : errors.length ? "PARTIAL" : "OK";
  const summary = summarise(parsed);
  if (summary.unmappedDcs.length) warnings.push(`unmapped datacenters (add to lib/dedicated/regions.ts): ${summary.unmappedDcs.join(", ")}`);
  const error = errors.length ? errors.join("; ") : null;
  await db.dedicatedCatalogSync.update({
    where: { id: sync.id },
    data: {
      status,
      finishedAt: new Date(),
      durationMs: Date.now() - t0,
      plansSeen: summary.totalPlans,
      added, changed, removed, priceChanges, optionsSeen, availabilityRows,
      summary: summary as unknown as object,
      warnings: warnings.slice(0, 200),
      error,
    },
  });
  if (status === "FAILED") console.error(`[dedicated-catalog] sync FAILED: ${error}`);
  else console.log(`[dedicated-catalog] sync ${status}: ${summary.totalPlans} plans (+${added} ~${changed} -${removed}, ${priceChanges} price changes), ${availabilityRows} stock rows in ${Date.now() - t0}ms`);
  return { syncId: sync.id, status, plansSeen: summary.totalPlans, added, changed, removed, priceChanges, availabilityRows, warnings, error };
}

async function applyCatalog(subsidiary: string, kind: CatalogKind, items: ParsedItem[]) {
  let added = 0, changed = 0, removed = 0, priceChanges = 0, optionsSeen = 0;
  const now = new Date();
  const existing = new Map(
    (await db.dedicatedCatalogItem.findMany({ where: { subsidiary, catalog: kind }, select: { id: true, planCode: true, hash: true, monthlyCents: true, removedAt: true } })).map((r) => [r.planCode, r]),
  );
  const seen = new Set<string>();
  for (const it of items) {
    if (seen.has(it.planCode)) continue; // upstream duplicates: first wins
    seen.add(it.planCode);
    optionsSeen += it.options.length;
    const hash = itemHash(it);
    const prev = existing.get(it.planCode);
    if (!prev) {
      const row = await db.dedicatedCatalogItem.create({ data: { ...upstreamData(it, subsidiary, hash), firstSeenAt: now, lastSeenAt: now } });
      await writeOptions(row.id, it, now);
      added++;
      continue;
    }
    if (prev.hash === hash && !prev.removedAt) continue; // unchanged; lastSeenAt bumped in bulk below
    const priceMoved = prev.monthlyCents !== it.monthlyCents;
    await db.dedicatedCatalogItem.update({
      where: { id: prev.id },
      data: {
        ...upstreamData(it, subsidiary, hash),
        lastSeenAt: now,
        removedAt: null,
        ...(priceMoved ? { priceChangedAt: now, previousMonthlyCents: prev.monthlyCents } : {}),
      },
    });
    await writeOptions(prev.id, it, now);
    changed++;
    if (priceMoved) priceChanges++;
  }
  await db.dedicatedCatalogItem.updateMany({ where: { subsidiary, catalog: kind, planCode: { in: [...seen] } }, data: { lastSeenAt: now } });
  const gone = [...existing.values()].filter((r) => !seen.has(r.planCode) && !r.removedAt).map((r) => r.id);
  if (gone.length) {
    await db.dedicatedCatalogItem.updateMany({ where: { id: { in: gone } }, data: { removedAt: now } });
    removed = gone.length;
  }
  return { added, changed, removed, priceChanges, optionsSeen };
