async function writeOptions(itemId: string, it: ParsedItem, now: Date) {
  const seen = new Set<string>();
  for (const o of it.options) {
    if (seen.has(o.planCode)) continue;
    seen.add(o.planCode);
    const data = {
      family: o.family,
      productCode: o.productCode,
      label: o.label,
      isDefault: o.isDefault,
      mandatory: o.mandatory,
      monthlyCents: o.monthlyCents,
      setupCents: o.setupCents,
      ramGb: o.ramGb,
      storageGb: o.storageGb,
      bandwidthMbps: o.bandwidthMbps,
      trafficTb: o.trafficTb,
      spec: o.spec as object,
      lastSeenAt: now,
      removedAt: null,
    };
    await db.dedicatedCatalogOption.upsert({ where: { itemId_planCode: { itemId, planCode: o.planCode } }, create: { itemId, planCode: o.planCode, ...data }, update: data });
  }
  await db.dedicatedCatalogOption.updateMany({ where: { itemId, planCode: { notIn: [...seen] }, removedAt: null }, data: { removedAt: now } });
}

/* ---------------- worker tick ---------------- */

let tickRunning = false;

/** Called every minute by the worker sweep runner; self-throttled. */
export async function dedicatedCatalogTick(now = new Date()): Promise<void> {
  if (tickRunning) return;
  tickRunning = true;
  try {
    const [enabledRaw, hoursRaw, requestedRaw] = await Promise.all([
      getSetting("dedicated_catalog_sync_enabled", "true"),
      getSetting("dedicated_catalog_sync_hours", "6"),
      getSetting("dedicated_catalog_sync_requested", ""),
    ]);
    const last = await db.dedicatedCatalogSync.findFirst({ orderBy: { startedAt: "desc" }, select: { startedAt: true } }).catch(() => null);
    const requested = requestedRaw.trim() !== "";
    if (!syncDue({ enabled: enabledRaw === "true", lastStartedAt: last?.startedAt ?? null, intervalHours: Number(hoursRaw), requested, now })) return;
    if (requested) await setSetting("dedicated_catalog_sync_requested", "");
    const requestedById = requested ? requestedRaw.split("|")[0] || null : null;
    await runCatalogSync({ trigger: requested ? "admin" : "worker", requestedById });
  } catch (e) {
    console.error("[dedicated-catalog] tick error", e);
  } finally {
    tickRunning = false;
  }
}

