/**
 * Bridge to the custom-offers feature (branch feature/chat-offers, OfferKind
 * DEDICATED). That branch is not merged yet, so:
 *   - `offersAvailable()` checks at RUNTIME whether the Prisma client has the
 *     Offer model; the admin "Create offer from this item" button is a stub
 *     that explains the dependency until it does;
 *   - `dedicatedOfferPrefill()` is the pure field mapping from a catalogue
 *     build onto the offer composer's inputs (OfferInput: kind, title,
 *     cpuCores, ramMB, diskGB, storageTier, bandwidthTB, region,
 *     renewalMonthlyCents, setupFeeCents, internalNote). Upstream identifiers
 *     go ONLY into internalNote (staff-only, never shown to the customer).
 *   - `offerComposerHref()` is the link the button uses once merged; the
 *     offers page needs a small follow-up to read `catalogItem` + the prefill
 *     query (documented in docs/DOCUMENTATION.md).
 * A DedicatedServer created from a PAID DEDICATED offer stores `offerId`.
 */
import { db } from "../db";

export function offersAvailable(): boolean {
  return typeof (db as unknown as Record<string, unknown>).offer === "object";
}

export type DedicatedOfferPrefill = {
  kind: "DEDICATED";
  title: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  storageTier: "nvme" | "hdd";
  bandwidthTB: number;
  region: string;
  renewalMonthlyCents: number;
  setupFeeCents: number;
  termMonths: 1;
  internalNote: string;
  catalogItemId: string;
};

export function dedicatedOfferPrefill(args: {
  itemId: string;
  customerName: string;
  cpuLabel: string;
  cores: number;
  ramGb: number | null;
  storageGb: number | null;
  storageLabel: string | null;
  trafficTb: number | null;
  region: string;
  sellMonthlyCents: number;
  sellSetupCents: number;
  upstreamPlanCode: string;
  upstreamDatacenter: string | null;
}): DedicatedOfferPrefill {
  const nvme = /nvme|ssd/i.test(args.storageLabel ?? "");
  return {
    kind: "DEDICATED",
    title: `Dedicated server · ${args.customerName}`.slice(0, 120),
    cpuCores: args.cores,
    ramMB: (args.ramGb ?? 0) * 1024,
    diskGB: args.storageGb ?? 0,
    storageTier: nvme || !args.storageLabel ? "nvme" : "hdd",
    // 0 = unmetered in the catalogue; the offer form treats 0 as "not stated".
    bandwidthTB: args.trafficTb ?? 0,
    region: args.region,
    renewalMonthlyCents: args.sellMonthlyCents,
    setupFeeCents: args.sellSetupCents,
    termMonths: 1,
    internalNote: `Catalogue build: ${args.upstreamPlanCode}${args.upstreamDatacenter ? ` @ ${args.upstreamDatacenter}` : ""}. Order + build by hand (no automation).`,
    catalogItemId: args.itemId,
  };
}

export function offerComposerHref(p: DedicatedOfferPrefill, userId?: string): string {
  const q = new URLSearchParams({
    new: "1",
    kind: p.kind,
    catalogItem: p.catalogItemId,
    cpu: String(p.cpuCores),
    ramGB: String(p.ramMB / 1024),
    disk: String(p.diskGB),
    tier: p.storageTier,
    bw: String(p.bandwidthTB),
    region: p.region,
    renewal: (p.renewalMonthlyCents / 100).toFixed(2),
    setupFee: (p.setupFeeCents / 100).toFixed(2),
    title: p.title,
  });
  if (userId) q.set("userId", userId);
  return `/admin/offers?${q.toString()}`;
}

