/**
 * Loader for the PUBLIC catalogue (marketing page + its admin preview).
 * Returns only brand-safe PublicCatalogEntry rows (lib/dedicated/customer-view.ts).
 *
 * Only items an admin marked `visible`, not removed upstream, priced in USD,
 * and orderable in at least one OFFERED, non-hidden region are listed.
 * `previewAll` (admin preview only) treats every live item as visible so the
 * page design can be reviewed before any item is opted in.
 */
import { db } from "../db";
import { defaultConfig, itemRegions, loadAvailability, loadRules, priceView, stockByDc } from "./catalog-view";
import { toPublicCatalogEntry, type PublicCatalogEntry } from "./customer-view";
import { sellMonthlyCents } from "./pricing";

export async function loadPublicCatalog(opts: { previewAll?: boolean; limit?: number } = {}): Promise<PublicCatalogEntry[]> {
  const { rules, enabledRegions } = await loadRules();
  const items = await db.dedicatedCatalogItem.findMany({
    where: { removedAt: null, currency: "USD", ...(opts.previewAll ? {} : { visible: true }) },
    include: { options: true },
    orderBy: { monthlyCents: "asc" },
  });
  const avail = await loadAvailability(items.map((i) => i.planCode));
  const out: PublicCatalogEntry[] = [];
  for (const it of items) {
    const stock = stockByDc(avail.get(it.planCode) ?? [], defaultConfig(it.options));
    const regions = itemRegions(it.datacenters, stock, enabledRegions, it.hiddenRegions);
    const entry = toPublicCatalogEntry(it, priceView(it, rules), regions, (cost) => sellMonthlyCents(0, { ...rules, markupFixedCents: 0, rounding: "none" }, { markupPercent: it.markupPercent }, cost));
    if (entry.regions.length === 0) continue;
    out.push(entry);
  }
  // One card per hardware build: regional variants of the same build merge their regions (cheapest price wins).
  const merged = new Map<string, PublicCatalogEntry>();
  for (const e of out) {
    const key = `${e.cpu}|${e.ramGb}|${e.storage}`;
    const prev = merged.get(key);
    if (!prev) {
      merged.set(key, { ...e, regions: [...e.regions] });
      continue;
    }
    for (const r of e.regions) if (!prev.regions.some((x) => x.code === r.code)) prev.regions.push(r);
    if (e.monthlyCents < prev.monthlyCents) Object.assign(prev, { ...e, regions: prev.regions });
  }
  const list = [...merged.values()].sort((a, b) => a.tierOrder - b.tierOrder || a.monthlyCents - b.monthlyCents);
  return opts.limit ? list.slice(0, opts.limit) : list;
}

