import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { PromoBar } from "@/components/marketing/PromoBar";
import { PromoTrialPopup } from "@/components/marketing/PromoTrialPopup";
import VisitTracker from "@/components/VisitTracker";
import { CurrencyProvider } from "@/components/currency/CurrencyContext";
import { resolveDisplayCurrency } from "@/lib/currency-display";
import { isTrialCampaignActive } from "@/lib/promo-trial";

export default async function MarketingLayout({ children }: { children: React.ReactNode }) {
  // Resolve the visitor's DISPLAY currency + FX rates once per request (cookie
  // override → geo header → configured default) and make them available to every
  // price component through context. DISPLAY ONLY — the charge currency stays USD.
  const { currency, rates } = await resolveDisplayCurrency();
  return (
    <CurrencyProvider initialCurrency={currency} rates={rates}>
      <div className="flex min-h-screen flex-col">
        <VisitTracker />
        {/* The 2026-09-22 7-day trial popup. Owner's call: mute the evergreen
            shared-hosting PromoBar strip for the duration of this campaign
            rather than stack two different $-off offers.
            `.marketing-promo-stack` (app/globals.css) re-pins the popup's own
            sticky countdown bar (`.promo-bar`) to sit BELOW MarketingHeader's
            72px-tall sticky bar instead of at the same `top: 0` — both used
            to be independently `position: sticky; top: 0`, so scrolling past
            either one made them occupy the exact same slot: the bar's higher
            z-index (55 vs the header's 50) drew it OVER the header, hiding
            the nav's own dropdowns/mobile-drawer CTAs behind it. See the CSS
            comment for why this is scoped to marketing rather than editing
            `.promo-bar` itself (also used, unmodified, in the dashboard,
            where the topbar is a different height). */}
        <div className="marketing-promo-stack">
          <PromoTrialPopup />
          {!isTrialCampaignActive() && <PromoBar />}
        </div>
        <MarketingHeader />
        <main className="flex-1">{children}</main>
        <MarketingFooter />
      </div>
    </CurrencyProvider>

