  const regions = useMemo(() => Array.from(new Map(entries.flatMap((e) => e.regions.map((r) => [r.code, r.label] as const))).entries()), [entries]);
  const [tier, setTier] = useState<string>("All");
  const [region, setRegion] = useState<string>("All");
  const [inStock, setInStock] = useState(false);
  const [sort, setSort] = useState<Sort>("price");

  const shown = useMemo(() => {
    const rows = entries
      .map((e) => {
        const rs = region === "All" ? e.regions : e.regions.filter((r) => r.code === region);
        const avail = inStock ? rs.filter((r) => r.stock === "in-stock" || r.stock === "limited") : rs;
        const from = avail.length ? Math.min(...avail.map((r) => r.monthlyCents)) : e.monthlyCents;
        return { e, regions: avail, from };
      })
      .filter((x) => (tier === "All" || x.e.tier === tier) && x.regions.length > 0);
    rows.sort((a, b) => (sort === "price" ? a.from - b.from : sort === "cores" ? b.e.cores - a.e.cores : (b.e.ramGb ?? 0) - (a.e.ramGb ?? 0)));
    return rows;
  }, [entries, tier, region, inStock, sort]);

  return (
    <div>
      <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
        <div className="-mx-1 flex flex-wrap gap-1.5" role="group" aria-label="Filter by tier">
          {["All", ...tiers].map((t) => (
            <button key={t} type="button" onClick={() => setTier(t)} aria-pressed={tier === t}
              className={`mx-1 rounded-full border px-3 py-1.5 text-xs font-semibold transition ${tier === t ? "border-brand-400/60 bg-brand-500/20 text-white" : "border-white/10 text-slate-300 hover:border-white/25"}`}>
              {t}
            </button>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2 text-xs">
          <label className="flex items-center gap-2 text-slate-300">
            <span className="sr-only">Location</span>
            <select value={region} onChange={(e) => setRegion(e.target.value)} className="input py-1.5 text-xs">
              <option value="All">All locations</option>
              {regions.map(([code, label]) => <option key={code} value={code}>{label}</option>)}
            </select>
          </label>
          <select value={sort} onChange={(e) => setSort(e.target.value as Sort)} className="input py-1.5 text-xs" aria-label="Sort">
            <option value="price">Lowest price</option>
            <option value="cores">Most cores</option>
            <option value="ram">Most memory</option>
          </select>
          <label className="flex cursor-pointer items-center gap-2 rounded-full border border-white/10 px-3 py-1.5 text-slate-300">
            <input type="checkbox" checked={inStock} onChange={(e) => setInStock(e.target.checked)} className="accent-[#22d3ee]" />
            In stock now
          </label>
        </div>
      </div>

      <p className="mt-4 text-xs text-slate-500">{shown.length} build{shown.length === 1 ? "" : "s"} · prices in USD per month, billed monthly</p>

      {shown.length === 0 ? (
        <div className="card mt-4 text-center text-sm text-slate-400">Nothing matches those filters right now. Clear a filter, or ask us for a custom build.</div>
      ) : (
        <ul className="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          {shown.map(({ e, regions: rs, from }) => (
            <li key={e.id} className="card lift relative flex flex-col overflow-hidden p-0">
              <div className="flex items-start justify-between gap-3 border-b border-white/[0.06] px-5 pb-4 pt-5">
                <div className="min-w-0">
                  <span className="eyebrow text-[10px]">{e.tier}</span>
                  <h3 className="mt-1 truncate text-lg font-bold tracking-tight text-white">{e.cpu}</h3>
                  <p className="text-xs text-slate-400">
                    {e.cores} cores / {e.threads} threads{e.baseGhz ? ` · ${e.baseGhz} GHz` : ""}{e.boostGhz ? ` (boost ${e.boostGhz} GHz)` : ""}
                  </p>
                </div>
                <div className="shrink-0 text-right">
                  <div className="text-[10px] uppercase tracking-wider text-slate-500">from</div>
                  <div className="text-xl font-bold text-white">{usd(from)}</div>
                  <div className="text-[11px] text-slate-500">/month</div>
                </div>
              </div>
              <dl className="grid grid-cols-2 gap-x-4 gap-y-3 px-5 py-4 text-sm">
                <div>
                  <dt className="text-[11px] uppercase tracking-wider text-slate-500">Memory</dt>
                  <dd className="font-semibold text-slate-100">{e.ramGb ? `${e.ramGb} GB` : "—"}{e.ram.length > 1 && <span className="ml-1 text-xs font-normal text-slate-500">up to {Math.max(...e.ram.map((r) => Number(/\d+/.exec(r.label)?.[0] ?? 0)))} GB</span>}</dd>
                </div>
                <div>
                  <dt className="text-[11px] uppercase tracking-wider text-slate-500">Network</dt>
                  <dd className="font-semibold text-slate-100">{e.bandwidth.replace(" public bandwidth", "") || "—"}</dd>
                </div>
                <div className="col-span-2">
                  <dt className="text-[11px] uppercase tracking-wider text-slate-500">Storage</dt>
                  <dd className="text-slate-100">{e.storage || "—"}{e.disks.length > 1 && <span className="ml-1 text-xs text-slate-500">+{e.disks.length - 1} more layouts</span>}</dd>
                </div>
              </dl>
              <div className="mt-auto space-y-3 px-5 pb-5">
                <ul className="flex flex-wrap gap-1.5" aria-label="Locations">
                  {rs.map((r) => (
                    <li key={r.code} className="flex items-center gap-1.5 rounded-full border border-white/10 bg-white/[0.03] px-2.5 py-1 text-[11px] text-slate-300" title={`${r.label}: ${PUBLIC_STOCK_LABEL[r.stock]} · ${usd(r.monthlyCents)}/mo`}>
                      <span className={`h-1.5 w-1.5 rounded-full ${STOCK_DOT[r.stock]}`} aria-hidden />
                      {r.label}
                      <span className="sr-only">: {PUBLIC_STOCK_LABEL[r.stock]}</span>
                    </li>
                  ))}
                </ul>
                <div className="flex items-center justify-between gap-3">
                  <span className="text-[11px] text-slate-500">{e.setupCents > 0 ? `${usd(e.setupCents)} one-time setup` : "No setup fee"}</span>
                  <a href={`${requestHref}${requestHref.includes("?") ? "&" : "?"}build=${encodeURIComponent(e.id)}`} className="btn-primary px-3 py-1.5 text-xs">Request this build</a>
                </div>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

