  const reveal = () =>
    start(async () => {
      if (preview) { setCred({ username: view.credentialsUser ?? "root", secret: "•••• preview ••••" }); return; }
      const r = await revealDedicatedCredentials(view.id);
      if (r.ok) setCred({ username: r.username, secret: r.secret });
      else setMsg(r.error);
    });

  return (
    <div className="mx-auto flex w-full max-w-[1180px] flex-col gap-4">
      {/* HEADER */}
      <header className="card relative overflow-hidden">
        <div aria-hidden className="hero-aura pointer-events-none absolute inset-0 opacity-70" />
        <div className="relative flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div className="min-w-0">
            <span className="eyebrow text-[11px]">Dedicated server</span>
            <h1 className="mt-1 truncate text-2xl font-bold tracking-tight text-white sm:text-3xl">{view.label}</h1>
            <p className="mt-1 truncate text-sm text-slate-400">{view.hostname ?? "Hostname assigned at handover"} · {view.region}</p>
          </div>
          <span className={`inline-flex w-fit items-center gap-2 rounded-full border px-3 py-1 text-xs font-semibold ${STATUS_TONE[view.statusKey] ?? STATUS_TONE.PENDING}`}>
            <span className={`h-1.5 w-1.5 rounded-full ${live ? "bg-accent-cyan shadow-[0_0_8px_rgb(34_211_238/0.9)]" : "bg-current"}`} aria-hidden />
            {view.status}
          </span>
        </div>
        {view.statusKey === "SUSPENDED" && (
          <p className="relative mt-4 rounded-xl border border-amber-400/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-100">
            This server is suspended{view.suspendReason ? `: ${view.suspendReason}` : "."} Contact support to restore it.
          </p>
        )}
        {(view.statusKey === "PENDING" || view.statusKey === "PROVISIONING") && (
          <p className="relative mt-4 text-xs text-slate-400">Our team is preparing this machine. Its IP addresses and login details will appear here when it is handed over.</p>
        )}
      </header>

      {/* SPECS */}
      <section aria-label="Hardware" className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        {[
          ["Processor", view.cpu, `${view.cores} cores · ${view.threads} threads`],
          ["Memory", `${view.ramGb} GB`, "Dedicated to this server"],
          ["Storage", view.storage.split("(")[0] || "—", view.storage.match(/\(([^)]+)\)/)?.[1] ?? ""],
          ["Network", view.bandwidth || "—", "Always-on DDoS protection"],
        ].map(([k, v, sub]) => (
          <div key={k} className="card p-4">
            <div className="text-[11px] uppercase tracking-wider text-slate-500">{k}</div>
            <div className="mt-1 truncate text-sm font-semibold text-white" title={v}>{v}</div>
            {sub && <div className="mt-0.5 truncate text-[11px] text-slate-500">{sub}</div>}
          </div>
        ))}
      </section>

      <div className="grid gap-4 lg:grid-cols-[1.4fr_1fr]">
        <div className="flex flex-col gap-4">
          {/* NETWORK */}
          <section className="card">
            <h2 className="text-sm font-semibold text-white">IP addresses</h2>
            {view.ipv4.length + view.ipv6.length === 0 ? (
              <p className="mt-2 text-xs text-slate-400">Assigned at handover.</p>
            ) : (
              <ul className="mt-3 divide-y divide-white/[0.06]">
                {view.ipv4.map((ip, i) => (
                  <li key={ip} className="flex items-center justify-between gap-3 py-2">
                    <CopyIp ip={ip} />
                    <span className="text-[11px] text-slate-500">IPv4{i === 0 ? " · primary" : ""}</span>
                  </li>
                ))}
                {view.ipv6.map((ip) => (
                  <li key={ip} className="flex items-center justify-between gap-3 py-2">
                    <CopyIp ip={ip} />
                    <span className="text-[11px] text-slate-500">IPv6</span>
                  </li>
                ))}
              </ul>
            )}
            <p className="mt-3 text-[11px] text-slate-500">Operating system: {view.os ?? "chosen at handover"}</p>
          </section>

          {/* BANDWIDTH placeholder — honest: no fake graph */}
          <section className="card">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-semibold text-white">Bandwidth</h2>
              <span className="rounded-full border border-white/10 px-2 py-0.5 text-[10px] uppercase tracking-wider text-slate-500">Coming soon</span>
            </div>
            <div className="mt-4 flex h-28 items-end gap-1" aria-hidden>
              {Array.from({ length: 36 }).map((_, i) => (
                <span key={i} className="flex-1 rounded-t-sm bg-white/[0.04]" style={{ height: `${18 + ((i * 37) % 60)}%` }} />
              ))}
            </div>
            <p className="mt-3 text-xs text-slate-400">Traffic graphs for dedicated servers are on their way. Until then, ask support for a usage report any time.</p>
          </section>

          {/* REQUESTS */}
          <section className="card">
            <h2 className="text-sm font-semibold text-white">Server actions</h2>
            <p className="mt-1 text-xs text-slate-400">Our engineers carry these out for you. Each one opens a support ticket so you can follow it.</p>
            <div className="mt-4 grid gap-2 sm:grid-cols-3">
              {(Object.keys(REQUEST_LABEL) as RequestKind[]).map((k) => (
                <button key={k} type="button" disabled={pending || !live || requested.has(k)} onClick={() => { setOpen(k); setMsg(null); }}
                  className="btn-ghost justify-start border border-white/10 py-2.5 text-left text-xs disabled:opacity-40">
                  <span>
                    <span className="block font-semibold text-white">{requested.has(k) ? `${REQUEST_LABEL[k]} · requested` : `Request ${REQUEST_LABEL[k].toLowerCase()}`}</span>
                    <span className="block font-normal text-slate-500">{REQUEST_HINT[k]}</span>
                  </span>
                </button>
              ))}
            </div>
            {!live && <p className="mt-3 text-[11px] text-slate-500">Available once the server is online.</p>}
            {open && (
              <div className="mt-4 rounded-xl border border-brand-400/30 bg-brand-500/[0.06] p-4">
                <label className="text-xs font-semibold text-white" htmlFor="ded-note">{REQUEST_LABEL[open]}: anything we should know?</label>
                <textarea id="ded-note" value={note} onChange={(e) => setNote(e.target.value)} rows={3} maxLength={2000}
                  placeholder={open === "REINSTALL" ? "e.g. Ubuntu 24.04, keep the same hostname" : "Optional"} className="input mt-2 w-full text-sm" />
                {open === "REINSTALL" && <p className="mt-2 text-[11px] text-amber-200">A reinstall erases everything on the disks.</p>}
                <div className="mt-3 flex gap-2">
                  <button type="button" className="btn-primary px-3 py-1.5 text-xs" disabled={pending} onClick={() => send(open)}>Send request</button>
                  <button type="button" className="btn-ghost px-3 py-1.5 text-xs" onClick={() => setOpen(null)}>Cancel</button>
                </div>
              </div>
            )}
            {msg && <p className="mt-3 text-xs text-slate-300" role="status">{msg}</p>}
            {view.openRequests.length > 0 && (
              <ul className="mt-4 space-y-1 text-[11px] text-slate-400">
                {view.openRequests.map((r) => (
                  <li key={r.id}>{REQUEST_LABEL[r.kind as RequestKind] ?? r.kind} requested {day(r.createdAt)} · with our team</li>
                ))}
              </ul>
            )}
          </section>
        </div>

        <div className="flex flex-col gap-4">
          {/* CREDENTIALS */}
          <section className="card">
            <h2 className="text-sm font-semibold text-white">Login details</h2>
            {view.credentialsReady ? (
              cred ? (
                <dl className="mt-3 space-y-2 text-sm">
                  <div className="flex justify-between gap-3"><dt className="text-slate-500">Username</dt><dd className="font-mono text-white">{cred.username}</dd></div>
                  <div className="flex justify-between gap-3"><dt className="text-slate-500">Password</dt><dd className="break-all font-mono text-white">{cred.secret}</dd></div>
                  <p className="pt-1 text-[11px] text-slate-500">Change this password after your first login.</p>
                </dl>
              ) : (
                <div className="mt-3">
                  <p className="text-xs text-slate-400">Your login is ready. It is stored encrypted and shown only to you.</p>
                  <button type="button" className="btn-primary mt-3 px-3 py-1.5 text-xs" disabled={pending} onClick={reveal}>Show login details</button>
                </div>
              )
            ) : (
              <p className="mt-2 text-xs text-slate-400">Delivered here as soon as your server is handed over.</p>
            )}
          </section>

          {/* BILLING */}
          <section className="card">
            <h2 className="text-sm font-semibold text-white">Billing</h2>
            <dl className="mt-3 space-y-2 text-sm">
              <div className="flex justify-between gap-3"><dt className="text-slate-500">Price</dt><dd className="text-white">{view.renewalMonthlyCents != null ? `${usd(view.renewalMonthlyCents)}/mo` : "—"}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-slate-500">Billing term</dt><dd className="text-white">{view.termMonths === 1 ? "Monthly" : `${view.termMonths} months`}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-slate-500">Next renewal</dt><dd className="text-white">{view.renewalDate ? day(view.renewalDate) : "—"}</dd></div>
            </dl>
            <p className="mt-3 text-[11px] text-slate-500">We send a renewal invoice before this date.</p>
            <h3 className="mt-5 text-xs font-semibold uppercase tracking-wider text-slate-500">Invoices</h3>
            {invoices.length === 0 ? (
              <p className="mt-2 text-xs text-slate-400">No invoices yet.</p>
            ) : (
              <ul className="mt-2 divide-y divide-white/[0.06]">
                {invoices.map((inv) => (
                  <li key={inv.id} className="flex items-center justify-between gap-3 py-2 text-xs">
                    {preview ? (
                      <span className="text-slate-200">#{inv.number} · {day(inv.createdAt)}</span>
                    ) : (
                      <Link href={`/dashboard/billing/invoices/${inv.id}`} className="text-slate-200 hover:text-white">#{inv.number} · {day(inv.createdAt)}</Link>
                    )}
                    <span className="text-slate-400">{usd(inv.amountCents)} · {inv.status.toLowerCase()}</span>
                  </li>
                ))}
              </ul>
            )}
          </section>

          <section className="card text-xs text-slate-400">
            Need something else on this server? <Link href={preview ? "#" : "/dashboard/support"} className="text-brand-300 hover:text-brand-200">Open a support ticket</Link>.
          </section>
        </div>
      </div>
    </div>
  );
}

