import type { Metadata } from "next";
import { requireDedicatedPublic, dedicatedPublicEnabled } from "@/lib/dedicated/gate";
import { loadPublicCatalog } from "@/lib/dedicated/public-catalog";
import { DedicatedMarketing } from "@/components/dedicated/DedicatedMarketing";

/**
 * Public dedicated-server page. UNRELEASED: 404s until Setting
 * dedicated_public_enabled is on (lib/dedicated/gate.ts). Admins review it at
 * /admin/preview/dedicated. Not in the sitemap while the flag is off.
 */
export const dynamic = "force-dynamic";

export async function generateMetadata(): Promise<Metadata> {
  const on = await dedicatedPublicEnabled();
  return {
    title: "Dedicated Servers — single-tenant bare metal",
    description: "Single-tenant dedicated servers with full root, dedicated IPv4 and always-on DDoS protection, in Nxeon regions. Live stock and monthly pricing.",
    alternates: { canonical: "/dedicated-servers" },
    robots: on ? { index: true, follow: true } : { index: false, follow: false },
  };
}

export default async function DedicatedServersPage() {
  await requireDedicatedPublic();
  const entries = await loadPublicCatalog();
  return <DedicatedMarketing entries={entries} />;
}
EOF
