import { notFound } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { requireDedicatedPublic } from "@/lib/dedicated/gate";
import { loadCustomerServer } from "@/lib/dedicated/customer-data";
import { DedicatedServerDashboard } from "@/components/dedicated/DedicatedServerDashboard";

/** One customer dedicated server. UNRELEASED: 404 until dedicated_public_enabled is on. */
