    <ul className="grid gap-3 md:grid-cols-2">
      {servers.map((s) => (
        <li key={s.id}>
          <Link href={`${hrefBase}/${s.id}`} className="card lift block p-5">
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0">
                <h3 className="truncate text-base font-semibold text-white">{s.label}</h3>
                <p className="truncate text-xs text-slate-400">{s.cpu} · {s.ramGb} GB · {s.region}</p>
              </div>
              <span className="shrink-0 text-xs font-semibold text-slate-300">{s.status}</span>
            </div>
            <p className="mt-3 font-mono text-xs text-slate-400">{s.ipv4[0] ?? "IP assigned at handover"}</p>
          </Link>
        </li>
      ))}
    </ul>
  );
}
