"use client";

/** ADMIN-ONLY controls for the dedicated-server admin pages. */
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  requestDedicatedCatalogSync,
  saveDedicatedPricingRules,
  setDedicatedPublicEnabled,
  saveDedicatedItemControls,
  createDedicatedServer,
  updateDedicatedServer,
  dedicatedLifecycle,
  deliverDedicatedCredentials,
  completeDedicatedRequest,
  addDedicatedNote,
  type DedicatedServerForm,
  type LifecycleAction,
} from "@/lib/actions-dedicated";

type R = { ok: true; id?: string } | { ok: false; error: string };

function useAct() {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const run = (fn: () => Promise<R>, okMsg = "Saved.", after?: (r: R) => void) =>
    start(async () => {
      const r = await fn();
      setMsg(r.ok ? okMsg : r.error);
      if (r.ok) router.refresh();
      after?.(r);
    });
  return { pending, msg, run };
}

export function SyncNowButton() {
  const { pending, msg, run } = useAct();
  return (
    <div className="flex items-center gap-3">
      <button type="button" className="btn-primary py-1.5 text-xs" disabled={pending} onClick={() => run(requestDedicatedCatalogSync, "Requested — the worker picks it up within a minute. Reload to see the result.")}>
        Sync now
      </button>
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
    </div>
  );
}

export function PublicFlagToggle({ on }: { on: boolean }) {
  const { pending, msg, run } = useAct();
  return (
    <div className="card flex items-start justify-between gap-4 p-4">
      <div>
        <h3 className="text-sm font-semibold">Customer &amp; public dedicated pages</h3>
        <p className="mt-1 text-xs text-slate-400">
          Off (default): /dedicated-servers and /dashboard/dedicated 404 and are not in the sitemap. Review them under Previews first.
        </p>
        <p className="mt-1 text-xs font-semibold text-slate-300">Currently {on ? "ON — public" : "OFF — private"}</p>
        {msg && <p className="mt-1 text-xs text-slate-400">{msg}</p>}
      </div>
      <button type="button" role="switch" aria-checked={on} disabled={pending}
        onClick={() => {
          if (!on && !confirm("Publish the dedicated-server page and customer dashboard?")) return;
          run(() => setDedicatedPublicEnabled(!on));
        }}
        className={`relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors disabled:opacity-50 ${on ? "bg-brand-500" : "bg-white/[0.12]"}`}>
        <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-[#fff] shadow transition ${on ? "translate-x-5" : "translate-x-0"}`} />
      </button>
    </div>
  );
}

export function PricingRulesForm(props: {
  markupPercent: number;
  markupFixedCents: number;
  rounding: string;
  setupPolicy: string;
  setupCustomCents: number;
  enabledRegions: string[];
  regions: { code: string; label: string; sold: boolean; plans: number }[];
  syncEnabled: boolean;
  syncHours: number;
}) {
  const { pending, msg, run } = useAct();
  const [f, setF] = useState({
    markupPercent: String(props.markupPercent),
    markupFixed: (props.markupFixedCents / 100).toFixed(2),
    rounding: props.rounding,
    setupPolicy: props.setupPolicy,
    setupCustom: (props.setupCustomCents / 100).toFixed(2),
    enabledRegions: props.enabledRegions,
    syncEnabled: props.syncEnabled,
    syncHours: String(props.syncHours),
  });
  const set = (k: keyof typeof f, v: unknown) => setF((p) => ({ ...p, [k]: v }));
  return (
    <form className="card space-y-5 p-5" onSubmit={(e) => { e.preventDefault(); run(() => saveDedicatedPricingRules(f)); }}>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <label className="text-xs text-slate-400">Markup %<input className="input mt-1 w-full" value={f.markupPercent} onChange={(e) => set("markupPercent", e.target.value)} inputMode="decimal" /></label>
        <label className="text-xs text-slate-400">Fixed markup ($/mo)<input className="input mt-1 w-full" value={f.markupFixed} onChange={(e) => set("markupFixed", e.target.value)} inputMode="decimal" /></label>
        <label className="text-xs text-slate-400">Rounding
          <select className="input mt-1 w-full" value={f.rounding} onChange={(e) => set("rounding", e.target.value)}>
            <option value="ninety-nine">Up to $X.99</option>
            <option value="whole">Up to whole dollar</option>
            <option value="five">Up to next $5</option>
            <option value="none">None (exact cents)</option>
          </select>
        </label>
        <label className="text-xs text-slate-400">Setup fee policy
          <select className="input mt-1 w-full" value={f.setupPolicy} onChange={(e) => set("setupPolicy", e.target.value)}>
            <option value="pass">Pass through our cost</option>
            <option value="waived">Waived (we absorb it)</option>
            <option value="custom">Custom fixed fee</option>
          </select>
        </label>
        {f.setupPolicy === "custom" && (
          <label className="text-xs text-slate-400">Custom setup fee ($)<input className="input mt-1 w-full" value={f.setupCustom} onChange={(e) => set("setupCustom", e.target.value)} inputMode="decimal" /></label>
        )}
      </div>
      <fieldset>
        <legend className="text-xs font-semibold text-slate-300">Regions we offer dedicated servers in</legend>
        <div className="mt-2 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
          {props.regions.map((r) => (
            <label key={r.code} className="flex items-center gap-2 rounded-lg border border-white/[0.06] px-3 py-2 text-xs">
              <input type="checkbox" checked={f.enabledRegions.includes(r.code)}
                onChange={(e) => set("enabledRegions", e.target.checked ? [...f.enabledRegions, r.code] : f.enabledRegions.filter((x) => x !== r.code))} />
              <span className="font-semibold">{r.label}</span>
              <span className="text-slate-500">{r.code}</span>
              <span className={`ml-auto rounded px-1.5 text-[10px] ${r.sold ? "bg-emerald-500/15 text-emerald-300" : "bg-amber-500/15 text-amber-300"}`}>{r.sold ? "we have nodes" : "not sold yet"}</span>
              <span className="text-[10px] text-slate-500">{r.plans}</span>
            </label>
          ))}
        </div>
      </fieldset>
      <div className="flex flex-wrap items-end gap-4">
        <label className="flex items-center gap-2 text-xs text-slate-300"><input type="checkbox" checked={f.syncEnabled} onChange={(e) => set("syncEnabled", e.target.checked)} /> Background catalogue sync</label>
        <label className="text-xs text-slate-400">Every (hours)<input className="input ml-2 w-20" value={f.syncHours} onChange={(e) => set("syncHours", e.target.value)} inputMode="numeric" /></label>
        <button className="btn-primary ml-auto py-1.5 text-xs" disabled={pending}>Save pricing rules</button>
      </div>
      {msg && <p className="text-xs text-slate-400">{msg}</p>}
    </form>
  );
}

export function ItemControlsForm(props: {
  itemId: string;
  visible: boolean;
  displayName: string;
  markupPercent: number | null;
  markupFixedCents: number | null;
  overrideMonthlyCents: number | null;
  setupPolicy: string | null;
  setupCustomCents: number | null;
  hiddenRegions: string[];
  adminNote: string;
  regions: { code: string; label: string }[];
}) {
  const { pending, msg, run } = useAct();
  const d = (c: number | null) => (c == null ? "" : (c / 100).toFixed(2));
  const [f, setF] = useState({
    visible: props.visible,
    displayName: props.displayName,
    markupPercent: props.markupPercent == null ? "" : String(props.markupPercent),
    markupFixed: d(props.markupFixedCents),
    overrideMonthly: d(props.overrideMonthlyCents),
    setupPolicy: props.setupPolicy ?? "",
    setupCustom: d(props.setupCustomCents),
    hiddenRegions: props.hiddenRegions,
    adminNote: props.adminNote,
  });
  const set = (k: keyof typeof f, v: unknown) => setF((p) => ({ ...p, [k]: v }));
  return (
    <form className="card space-y-4 p-5" onSubmit={(e) => { e.preventDefault(); run(() => saveDedicatedItemControls(props.itemId, f)); }}>
      <h3 className="text-sm font-semibold">Nxeon controls</h3>
      <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={f.visible} onChange={(e) => set("visible", e.target.checked)} /> Show in customer catalogue</label>
      <label className="block text-xs text-slate-400">Customer name (blank = generated, never the upstream name)<input className="input mt-1 w-full" value={f.displayName} onChange={(e) => set("displayName", e.target.value)} placeholder="e.g. Business EPYC 4244P" /></label>
      <div className="grid gap-3 sm:grid-cols-2">
        <label className="text-xs text-slate-400">Markup % (blank = global)<input className="input mt-1 w-full" value={f.markupPercent} onChange={(e) => set("markupPercent", e.target.value)} /></label>
        <label className="text-xs text-slate-400">Fixed markup $/mo (blank = global)<input className="input mt-1 w-full" value={f.markupFixed} onChange={(e) => set("markupFixed", e.target.value)} /></label>
        <label className="text-xs text-slate-400">Hard monthly price $ (blank = rule)<input className="input mt-1 w-full" value={f.overrideMonthly} onChange={(e) => set("overrideMonthly", e.target.value)} /></label>
        <label className="text-xs text-slate-400">Setup policy
          <select className="input mt-1 w-full" value={f.setupPolicy} onChange={(e) => set("setupPolicy", e.target.value)}>
            <option value="">Global default</option>
            <option value="pass">Pass through</option>
            <option value="waived">Waived</option>
            <option value="custom">Custom</option>
          </select>
        </label>
        {f.setupPolicy === "custom" && <label className="text-xs text-slate-400">Custom setup $<input className="input mt-1 w-full" value={f.setupCustom} onChange={(e) => set("setupCustom", e.target.value)} /></label>}
      </div>
      {props.regions.length > 0 && (
        <fieldset>
          <legend className="text-xs text-slate-400">Hide in these regions (this item only)</legend>
          <div className="mt-1 flex flex-wrap gap-2">
            {props.regions.map((r) => (
              <label key={r.code} className="flex items-center gap-1.5 rounded border border-white/[0.06] px-2 py-1 text-xs">
                <input type="checkbox" checked={f.hiddenRegions.includes(r.code)} onChange={(e) => set("hiddenRegions", e.target.checked ? [...f.hiddenRegions, r.code] : f.hiddenRegions.filter((x) => x !== r.code))} />
                {r.label}
              </label>
            ))}
          </div>
        </fieldset>
      )}
      <label className="block text-xs text-slate-400">Admin note<textarea className="input mt-1 w-full" rows={2} value={f.adminNote} onChange={(e) => set("adminNote", e.target.value)} /></label>
      <div className="flex items-center gap-3">
        <button className="btn-primary py-1.5 text-xs" disabled={pending}>Save</button>
        {msg && <span className="text-xs text-slate-400">{msg}</span>}
      </div>
    </form>
  );
}

const EMPTY: DedicatedServerForm = {
  userEmail: "", label: "", hostname: "", catalogItemId: "", offerId: "", cpu: "", cores: 0, threads: 0, ramGb: 0, storage: "", bandwidth: "",
  region: "sgp1", datacenter: "", providerServiceName: "", costMonthly: "", ipv4: "", ipv6: "", os: "", renewalDate: "", renewalMonthly: "",
  termMonths: 1, setupFee: "", invoiceIds: "", notes: "",
};

export function DedicatedServerFormView({ id, initial, regions }: { id?: string; initial?: Partial<DedicatedServerForm>; regions: { code: string; label: string }[] }) {
  const router = useRouter();
  const { pending, msg, run } = useAct();
  const [f, setF] = useState<DedicatedServerForm>({ ...EMPTY, ...initial });
  const set = (k: keyof DedicatedServerForm, v: unknown) => setF((p) => ({ ...p, [k]: v }));
  const field = (k: keyof DedicatedServerForm, label: string, extra: Record<string, unknown> = {}) => (
    <label className="text-xs text-slate-400">{label}<input className="input mt-1 w-full" value={String(f[k] ?? "")} onChange={(e) => set(k, e.target.value)} {...extra} /></label>
  );
  return (
    <form className="card space-y-4 p-5" onSubmit={(e) => {
      e.preventDefault();
      run(() => (id ? updateDedicatedServer(id, f) : createDedicatedServer(f)), id ? "Saved." : "Created.", (r) => { if (r.ok && !id && r.id) router.push(`/admin/dedicated/servers/${r.id}`); });
    }}>
      <h3 className="text-sm font-semibold">{id ? "Edit server" : "Add a managed dedicated server"}</h3>
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {field("userEmail", "Customer email *", { type: "email", required: true })}
        {field("label", "Label (customer sees) *", { required: true })}
        {field("hostname", "Hostname")}
        {field("cpu", "CPU *", { required: true })}
        {field("cores", "Cores", { inputMode: "numeric" })}
        {field("threads", "Threads", { inputMode: "numeric" })}
        {field("ramGb", "RAM (GB)", { inputMode: "numeric" })}
        {field("storage", "Storage")}
        {field("bandwidth", "Bandwidth")}
        <label className="text-xs text-slate-400">Region *
          <select className="input mt-1 w-full" value={f.region} onChange={(e) => set("region", e.target.value)}>
            {regions.map((r) => <option key={r.code} value={r.code}>{r.label} ({r.code})</option>)}
          </select>
        </label>
        {field("os", "OS")}
        {field("ipv4", "IPv4 (comma/space separated)")}
        {field("ipv6", "IPv6")}
        {field("renewalDate", "Renewal date", { type: "date" })}
        {field("renewalMonthly", "Customer price $/mo")}
        {field("termMonths", "Term (months)", { inputMode: "numeric" })}
        {field("setupFee", "Setup fee charged $")}
        {field("invoiceIds", "Linked invoice ids")}
        {field("catalogItemId", "Catalogue item id")}
        {field("offerId", "Offer id")}
      </div>
      <fieldset className="rounded-xl border border-amber-500/20 bg-amber-500/[0.04] p-3">
        <legend className="px-1 text-[11px] font-semibold uppercase tracking-wider text-amber-300">Admin only — never shown to the customer</legend>
        <div className="grid gap-3 sm:grid-cols-3">
          {field("providerServiceName", "Upstream service name")}
          {field("datacenter", "Upstream datacenter code")}
          {field("costMonthly", "Our cost $/mo")}
        </div>
        <label className="mt-3 block text-xs text-slate-400">Internal notes<textarea className="input mt-1 w-full" rows={3} value={f.notes ?? ""} onChange={(e) => set("notes", e.target.value)} /></label>
      </fieldset>
      <div className="flex items-center gap-3">
        <button className="btn-primary py-1.5 text-xs" disabled={pending}>{id ? "Save" : "Create"}</button>
        {msg && <span className="text-xs text-slate-400">{msg}</span>}
      </div>
    </form>
  );
}

export function LifecycleButtons({ id, status }: { id: string; status: string }) {
  const { pending, msg, run } = useAct();
  const go = (a: LifecycleAction, confirmText?: string, ask?: string) => {
    if (confirmText && !confirm(confirmText)) return;
    const reason = ask ? prompt(ask) ?? "" : "";
    run(() => dedicatedLifecycle(id, a, reason));
  };
  return (
    <div className="flex flex-wrap items-center gap-2">
      {status === "PENDING" && <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => go("provisioning")}>Mark build started</button>}
      {(status === "PENDING" || status === "PROVISIONING") && <button className="btn-primary py-1 text-xs" disabled={pending} onClick={() => go("provisioned", "Mark as provisioned (customer sees it Online)?")}>Mark provisioned</button>}
      {status === "ACTIVE" && <button className="btn-ghost py-1 text-xs text-amber-300" disabled={pending} onClick={() => go("suspend", "Suspend? Records state only — suspend the machine itself by hand.", "Reason shown to the customer (optional)")}>Suspend</button>}
      {status === "SUSPENDED" && <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => go("unsuspend")}>Unsuspend</button>}
      {status !== "CANCELLED" && <button className="btn-ghost py-1 text-xs text-red-300" disabled={pending} onClick={() => go("cancel", "Cancel this server? Remember to cancel the upstream service by hand.")}>Cancel</button>}
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
    </div>
  );
}

export function CredentialsForm({ id, delivered, username }: { id: string; delivered: boolean; username: string | null }) {
  const { pending, msg, run } = useAct();
  const [u, setU] = useState(username ?? "root");
  const [s, setS] = useState("");
  return (
    <form className="space-y-2" onSubmit={(e) => { e.preventDefault(); run(() => deliverDedicatedCredentials(id, u, s), "Delivered — the customer can reveal it in their dashboard.", (r) => { if (r.ok) setS(""); }); }}>
      <p className="text-xs text-slate-400">{delivered ? `Delivered (user ${username}). Saving again replaces it.` : "Not delivered yet."} Stored encrypted; never shown here again.</p>
      <div className="flex flex-wrap gap-2">
        <input className="input w-32" value={u} onChange={(e) => setU(e.target.value)} aria-label="Username" />
        <input className="input min-w-0 flex-1" type="password" value={s} onChange={(e) => setS(e.target.value)} placeholder="Password" aria-label="Password" autoComplete="new-password" />
        <button className="btn-primary py-1.5 text-xs" disabled={pending || s.length < 8}>Deliver</button>
      </div>
      {msg && <p className="text-xs text-slate-400">{msg}</p>}
    </form>
  );
}

export function RequestDoneButtons({ requestId }: { requestId: string }) {
  const { pending, msg, run } = useAct();
  return (
    <span className="flex items-center gap-2">
      <button className="btn-primary py-0.5 text-[11px]" disabled={pending} onClick={() => run(() => completeDedicatedRequest(requestId, "DONE"))}>Done</button>
      <button className="btn-ghost py-0.5 text-[11px]" disabled={pending} onClick={() => run(() => completeDedicatedRequest(requestId, "CANCELLED"))}>Cancel</button>
      {msg && <span className="text-[11px] text-slate-400">{msg}</span>}
    </span>
  );
}

export function NoteForm({ id }: { id: string }) {
  const { pending, msg, run } = useAct();
  const [n, setN] = useState("");
  return (
    <form className="flex gap-2" onSubmit={(e) => { e.preventDefault(); run(() => addDedicatedNote(id, n), "Noted.", (r) => { if (r.ok) setN(""); }); }}>
      <input className="input min-w-0 flex-1" value={n} onChange={(e) => setN(e.target.value)} placeholder="Add an audit note" />
      <button className="btn-ghost py-1.5 text-xs" disabled={pending || !n.trim()}>Add</button>
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
    </form>
  );
}

