      <button type="button" className="btn-primary py-1.5 text-xs" disabled={pending} onClick={() => run(requestDedicatedCatalogSync, "Requested — the worker picks it up within a minute. Reload to see the result.")}>
        Sync now
      </button>
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
    </div>
  );
}

export function PublicFlagToggle({ on }: { on: boolean }) {
  const { pending, msg, run } = useAct();
  return (
    <div className="card flex items-start justify-between gap-4 p-4">
      <div>
        <h3 className="text-sm font-semibold">Customer &amp; public dedicated pages</h3>
        <p className="mt-1 text-xs text-slate-400">
          Off (default): /dedicated-servers and /dashboard/dedicated 404 and are not in the sitemap. Review them under Previews first.
        </p>
        <p className="mt-1 text-xs font-semibold text-slate-300">Currently {on ? "ON — public" : "OFF — private"}</p>
        {msg && <p className="mt-1 text-xs text-slate-400">{msg}</p>}
      </div>
      <button type="button" role="switch" aria-checked={on} disabled={pending}
        onClick={() => {
          if (!on && !confirm("Publish the dedicated-server page and customer dashboard?")) return;
          run(() => setDedicatedPublicEnabled(!on));
        }}
        className={`relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors disabled:opacity-50 ${on ? "bg-brand-500" : "bg-white/[0.12]"}`}>
        <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-[#fff] shadow transition ${on ? "translate-x-5" : "translate-x-0"}`} />
