  const set = (k: keyof DedicatedServerForm, v: unknown) => setF((p) => ({ ...p, [k]: v }));
  const field = (k: keyof DedicatedServerForm, label: string, extra: Record<string, unknown> = {}) => (
    <label className="text-xs text-slate-400">{label}<input className="input mt-1 w-full" value={String(f[k] ?? "")} onChange={(e) => set(k, e.target.value)} {...extra} /></label>
