        <label className="mt-3 block text-xs text-slate-400">Internal notes<textarea className="input mt-1 w-full" rows={3} value={f.notes ?? ""} onChange={(e) => set("notes", e.target.value)} /></label>
      </fieldset>
      <div className="flex items-center gap-3">
        <button className="btn-primary py-1.5 text-xs" disabled={pending}>{id ? "Save" : "Create"}</button>
        {msg && <span className="text-xs text-slate-400">{msg}</span>}
      </div>
    </form>
  );
}

export function LifecycleButtons({ id, status }: { id: string; status: string }) {
  const { pending, msg, run } = useAct();
  const go = (a: LifecycleAction, confirmText?: string, ask?: string) => {
    if (confirmText && !confirm(confirmText)) return;
    const reason = ask ? prompt(ask) ?? "" : "";
    run(() => dedicatedLifecycle(id, a, reason));
  };
  return (
    <div className="flex flex-wrap items-center gap-2">
      {status === "PENDING" && <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => go("provisioning")}>Mark build started</button>}
      {(status === "PENDING" || status === "PROVISIONING") && <button className="btn-primary py-1 text-xs" disabled={pending} onClick={() => go("provisioned", "Mark as provisioned (customer sees it Online)?")}>Mark provisioned</button>}
      {status === "ACTIVE" && <button className="btn-ghost py-1 text-xs text-amber-300" disabled={pending} onClick={() => go("suspend", "Suspend? Records state only — suspend the machine itself by hand.", "Reason shown to the customer (optional)")}>Suspend</button>}
      {status === "SUSPENDED" && <button className="btn-ghost py-1 text-xs" disabled={pending} onClick={() => go("unsuspend")}>Unsuspend</button>}
      {status !== "CANCELLED" && <button className="btn-ghost py-1 text-xs text-red-300" disabled={pending} onClick={() => go("cancel", "Cancel this server? Remember to cancel the upstream service by hand.")}>Cancel</button>}
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
    </div>
  );
}

export function CredentialsForm({ id, delivered, username }: { id: string; delivered: boolean; username: string | null }) {
  const { pending, msg, run } = useAct();
  const [u, setU] = useState(username ?? "root");
  const [s, setS] = useState("");
  return (
    <form className="space-y-2" onSubmit={(e) => { e.preventDefault(); run(() => deliverDedicatedCredentials(id, u, s), "Delivered — the customer can reveal it in their dashboard.", (r) => { if (r.ok) setS(""); }); }}>
      <p className="text-xs text-slate-400">{delivered ? `Delivered (user ${username}). Saving again replaces it.` : "Not delivered yet."} Stored encrypted; never shown here again.</p>
      <div className="flex flex-wrap gap-2">
        <input className="input w-32" value={u} onChange={(e) => setU(e.target.value)} aria-label="Username" />
        <input className="input min-w-0 flex-1" type="password" value={s} onChange={(e) => setS(e.target.value)} placeholder="Password" aria-label="Password" autoComplete="new-password" />
        <button className="btn-primary py-1.5 text-xs" disabled={pending || s.length < 8}>Deliver</button>
      </div>
      {msg && <p className="text-xs text-slate-400">{msg}</p>}
    </form>
  );
}

export function RequestDoneButtons({ requestId }: { requestId: string }) {
  const { pending, msg, run } = useAct();
  return (
    <span className="flex items-center gap-2">
      <button className="btn-primary py-0.5 text-[11px]" disabled={pending} onClick={() => run(() => completeDedicatedRequest(requestId, "DONE"))}>Done</button>
      <button className="btn-ghost py-0.5 text-[11px]" disabled={pending} onClick={() => run(() => completeDedicatedRequest(requestId, "CANCELLED"))}>Cancel</button>
      {msg && <span className="text-[11px] text-slate-400">{msg}</span>}
    </span>
  );
}

export function NoteForm({ id }: { id: string }) {
  const { pending, msg, run } = useAct();
  const [n, setN] = useState("");
  return (
    <form className="flex gap-2" onSubmit={(e) => { e.preventDefault(); run(() => addDedicatedNote(id, n), "Noted.", (r) => { if (r.ok) setN(""); }); }}>
      <input className="input min-w-0 flex-1" value={n} onChange={(e) => setN(e.target.value)} placeholder="Add an audit note" />
      <button className="btn-ghost py-1.5 text-xs" disabled={pending || !n.trim()}>Add</button>
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
    </form>
  );
}

