import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, StatCard, Badge, EmptyState } from "@/components/ui/primitives";
import { SyncNowButton } from "@/components/admin/dedicated/Controls";
import { defaultConfig, itemRegions, loadAvailability, loadRules, priceView, stockByDc } from "@/lib/dedicated/catalog-view";
import { money } from "@/lib/dedicated/pricing";
import { stockLabel } from "@/lib/dedicated/ovh-catalog";
import { DEDICATED_DC_REGIONS } from "@/lib/dedicated/regions";
import { dedicatedPublicEnabled } from "@/lib/dedicated/gate";

export const dynamic = "force-dynamic";

/**
 * ADMIN-ONLY dedicated-server catalogue browser: the upstream bare-metal public
 * catalogue as last synced, with live stock per region, our cost vs Nxeon price
 * vs margin. Upstream names/plan codes appear ONLY in admin.
 */
type SP = { q?: string; range?: string; region?: string; minRam?: string; maxPrice?: string; inStock?: string; visible?: string; removed?: string; sort?: string };

const STOCK_TONE = (code: string) => (/^1H/.test(code) ? "bg-cyan-400" : /^\d+H/.test(code) ? "bg-brand-300" : code === "comingSoon" ? "bg-amber-300" : "bg-slate-600");

export default async function AdminDedicatedCatalogue({ searchParams }: { searchParams: Promise<SP> }) {
  await requireAdmin();
  const sp = await searchParams;
  const [{ rules, enabledRegions }, lastSync, lastOk, publicOn] = await Promise.all([
    loadRules(),
    db.dedicatedCatalogSync.findFirst({ orderBy: { startedAt: "desc" } }).catch(() => null),
    db.dedicatedCatalogSync.findFirst({ where: { status: { in: ["OK", "PARTIAL"] } }, orderBy: { startedAt: "desc" } }).catch(() => null),
    dedicatedPublicEnabled(),
  ]);
  const items = await db.dedicatedCatalogItem
    .findMany({ where: sp.removed === "1" ? {} : { removedAt: null }, include: { options: { select: { family: true, isDefault: true, productCode: true, removedAt: true, ramGb: true } } }, orderBy: { monthlyCents: "asc" } })
    .catch(() => null);
  if (items === null) {
    return (
      <div className="space-y-6">
        <PageHeader title="Dedicated catalogue" />
        <EmptyState title="Tables not migrated" sub="Run prisma db push on this database first." />
      </div>
    );
  }
  const avail = await loadAvailability(items.map((i) => i.planCode));

  const rows = items.map((it) => {
    const stock = stockByDc(avail.get(it.planCode) ?? [], defaultConfig(it.options));
    const regions = itemRegions(it.datacenters, stock, enabledRegions, it.hiddenRegions);
    const p = priceView(it, rules);
    const maxRam = Math.max(it.defaultRamGb ?? 0, ...it.options.filter((o) => o.family === "memory" && !o.removedAt).map((o) => o.ramGb ?? 0));
    return { it, regions, p, maxRam };
  });

  const q = (sp.q ?? "").trim().toLowerCase();
  const minRam = Number(sp.minRam) || 0;
  const maxPrice = Number(sp.maxPrice) || 0;
  const filtered = rows.filter(({ it, regions, p, maxRam }) => {
    if (sp.range && it.range !== sp.range) return false;
    if (q && !`${it.name} ${it.planCode} ${it.cpuBrand} ${it.cpuModel} ${it.invoiceName}`.toLowerCase().includes(q)) return false;
    if (minRam && maxRam < minRam) return false;
    if (maxPrice && p.sellMonthly > maxPrice * 100) return false;
    if (sp.visible === "1" && !it.visible) return false;
    const rs = sp.region ? regions.filter((r) => r.code === sp.region) : regions;
    if (sp.region && rs.length === 0) return false;
    if (sp.inStock === "1" && !rs.some((r) => r.inStock)) return false;
    return true;
  });
  if (sp.sort === "margin") filtered.sort((a, b) => b.p.margin.cents - a.p.margin.cents);
  else if (sp.sort === "cores") filtered.sort((a, b) => b.it.cpuThreads - a.it.cpuThreads);

  const ranges = Array.from(new Set(items.map((i) => i.range))).sort();
  const regionCodes = Array.from(new Map(Object.values(DEDICATED_DC_REGIONS).map((r) => [r.code, r.label])).entries());
  const live = rows.filter((r) => !r.it.removedAt);
  const inStockOffered = live.filter((r) => r.regions.some((g) => g.offered && g.inStock)).length;
  const summary = (lastOk?.summary ?? null) as null | { catalogs?: Record<string, { plans: number; ranges: Record<string, number> }>; unmappedDcs?: string[] };

  return (
    <div className="space-y-6">
      <PageHeader title="Dedicated catalogue" sub="Upstream bare-metal public catalogue (admin-only), live stock, our cost vs Nxeon price.">
