          <label className="flex items-center gap-1"><input type="checkbox" name="visible" value="1" defaultChecked={sp.visible === "1"} /> Visible</label>
          <label className="flex items-center gap-1"><input type="checkbox" name="removed" value="1" defaultChecked={sp.removed === "1"} /> Removed</label>
        </div>
