                  <td className="px-3 py-2">{it.visible ? <Badge tone="green">yes</Badge> : <Badge tone="slate">no</Badge>}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      <p className="text-[11px] text-slate-500">Stock dot: cyan = deliverable within ~1h upstream, violet = longer lead time, amber = coming soon, grey = out of stock / no data. Dashed chip = region not offered yet.</p>
    </div>
  );
}

