type SP = { q?: string; range?: string; region?: string; minRam?: string; maxPrice?: string; inStock?: string; visible?: string; removed?: string; sort?: string };

const STOCK_TONE = (code: string) => (/^1H/.test(code) ? "bg-cyan-400" : /^\d+H/.test(code) ? "bg-brand-300" : code === "comingSoon" ? "bg-amber-300" : "bg-slate-600");

export default async function AdminDedicatedCatalogue({ searchParams }: { searchParams: Promise<SP> }) {
  await requireAdmin();
  const sp = await searchParams;
  const [{ rules, enabledRegions }, lastSync, lastOk, publicOn] = await Promise.all([
    loadRules(),
    db.dedicatedCatalogSync.findFirst({ orderBy: { startedAt: "desc" } }).catch(() => null),
    db.dedicatedCatalogSync.findFirst({ where: { status: { in: ["OK", "PARTIAL"] } }, orderBy: { startedAt: "desc" } }).catch(() => null),
    dedicatedPublicEnabled(),
  ]);
  const items = await db.dedicatedCatalogItem
    .findMany({ where: sp.removed === "1" ? {} : { removedAt: null }, include: { options: { select: { family: true, isDefault: true, productCode: true, removedAt: true, ramGb: true } } }, orderBy: { monthlyCents: "asc" } })
    .catch(() => null);
  if (items === null) {
    return (
      <div className="space-y-6">
        <PageHeader title="Dedicated catalogue" />
        <EmptyState title="Tables not migrated" sub="Run prisma db push on this database first." />
      </div>
    );
  }
  const avail = await loadAvailability(items.map((i) => i.planCode));

  const rows = items.map((it) => {
    const stock = stockByDc(avail.get(it.planCode) ?? [], defaultConfig(it.options));
    const regions = itemRegions(it.datacenters, stock, enabledRegions, it.hiddenRegions);
    const p = priceView(it, rules);
    const maxRam = Math.max(it.defaultRamGb ?? 0, ...it.options.filter((o) => o.family === "memory" && !o.removedAt).map((o) => o.ramGb ?? 0));
    return { it, regions, p, maxRam };
  });

  const q = (sp.q ?? "").trim().toLowerCase();
  const minRam = Number(sp.minRam) || 0;
  const maxPrice = Number(sp.maxPrice) || 0;
  const filtered = rows.filter(({ it, regions, p, maxRam }) => {
    if (sp.range && it.range !== sp.range) return false;
    if (q && !`${it.name} ${it.planCode} ${it.cpuBrand} ${it.cpuModel} ${it.invoiceName}`.toLowerCase().includes(q)) return false;
    if (minRam && maxRam < minRam) return false;
    if (maxPrice && p.sellMonthly > maxPrice * 100) return false;
    if (sp.visible === "1" && !it.visible) return false;
    const rs = sp.region ? regions.filter((r) => r.code === sp.region) : regions;
    if (sp.region && rs.length === 0) return false;
    if (sp.inStock === "1" && !rs.some((r) => r.inStock)) return false;
    return true;
  });
  if (sp.sort === "margin") filtered.sort((a, b) => b.p.margin.cents - a.p.margin.cents);
  else if (sp.sort === "cores") filtered.sort((a, b) => b.it.cpuThreads - a.it.cpuThreads);

  const ranges = Array.from(new Set(items.map((i) => i.range))).sort();
  const regionCodes = Array.from(new Map(Object.values(DEDICATED_DC_REGIONS).map((r) => [r.code, r.label])).entries());
  const live = rows.filter((r) => !r.it.removedAt);
  const inStockOffered = live.filter((r) => r.regions.some((g) => g.offered && g.inStock)).length;
  const summary = (lastOk?.summary ?? null) as null | { catalogs?: Record<string, { plans: number; ranges: Record<string, number> }>; unmappedDcs?: string[] };

  return (
    <div className="space-y-6">
      <PageHeader title="Dedicated catalogue" sub="Upstream bare-metal public catalogue (admin-only), live stock, our cost vs Nxeon price.">
        <Link href="/admin/dedicated/pricing" className="btn-ghost py-1.5 text-xs">Pricing rules</Link>
        <Link href="/admin/preview/dedicated" className="btn-ghost py-1.5 text-xs">Preview public page</Link>
      </PageHeader>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard label="Plans in catalogue" value={String(live.length)} />
        <StatCard label="In stock in an offered region" value={String(inStockOffered)} />
        <StatCard label="Visible to customers" value={String(live.filter((r) => r.it.visible).length)} />
        <StatCard label="Public pages" value={publicOn ? "ON" : "OFF (private)"} />
      </div>

      <div className="card flex flex-col gap-3 p-4 lg:flex-row lg:items-center lg:justify-between">
        <div className="text-xs text-slate-400">
          {lastSync ? (
            <>
              Last sync <b className="text-slate-200">{lastSync.startedAt.toISOString().slice(0, 16).replace("T", " ")} UTC</b> ·{" "}
              <Badge tone={lastSync.status === "OK" ? "green" : lastSync.status === "PARTIAL" ? "amber" : lastSync.status === "RUNNING" ? "brand" : "red"}>{lastSync.status}</Badge>{" "}
              {lastSync.plansSeen} plans, {lastSync.availabilityRows} stock rows, +{lastSync.added} / ~{lastSync.changed} / -{lastSync.removed}, {lastSync.priceChanges} price changes
              {lastSync.durationMs ? ` in ${(lastSync.durationMs / 1000).toFixed(1)}s` : ""} · subsidiary {lastSync.subsidiary}
              {lastSync.error && <p className="mt-1 text-red-300">{lastSync.error}</p>}
              {summary?.catalogs && (
                <p className="mt-1">
                  {Object.entries(summary.catalogs).map(([k, c]) => `${k}: ${c.plans} plans (${Object.entries(c.ranges).map(([r, n]) => `${r} ${n}`).join(", ")})`).join(" · ")}
                </p>
              )}
              {summary?.unmappedDcs && summary.unmappedDcs.length > 0 && <p className="mt-1 text-amber-300">Unmapped datacenters: {summary.unmappedDcs.join(", ")} — add them to lib/dedicated/regions.ts</p>}
            </>
          ) : (
            "Never synced. Press Sync now (read-only public catalogue GETs)."
          )}
        </div>
        <SyncNowButton />
      </div>

      <form className="card grid gap-3 p-4 sm:grid-cols-3 lg:grid-cols-9" method="get">
        <input name="q" defaultValue={sp.q} placeholder="CPU / name / plan code" className="input lg:col-span-2" />
        <select name="range" defaultValue={sp.range ?? ""} className="input">
          <option value="">All ranges</option>
          {ranges.map((r) => <option key={r} value={r}>{r}</option>)}
        </select>
        <select name="region" defaultValue={sp.region ?? ""} className="input">
          <option value="">All regions</option>
          {regionCodes.map(([c, l]) => <option key={c} value={c}>{l}{enabledRegions.has(c) ? "" : " (not offered)"}</option>)}
        </select>
        <input name="minRam" defaultValue={sp.minRam} placeholder="Min RAM GB" inputMode="numeric" className="input" />
        <input name="maxPrice" defaultValue={sp.maxPrice} placeholder="Max Nxeon $/mo" inputMode="numeric" className="input" />
        <select name="sort" defaultValue={sp.sort ?? ""} className="input">
          <option value="">Sort: price</option>
          <option value="margin">Sort: margin</option>
          <option value="cores">Sort: threads</option>
        </select>
        <div className="flex flex-wrap items-center gap-3 text-xs text-slate-300 lg:col-span-1">
          <label className="flex items-center gap-1"><input type="checkbox" name="inStock" value="1" defaultChecked={sp.inStock === "1"} /> In stock</label>
          <label className="flex items-center gap-1"><input type="checkbox" name="visible" value="1" defaultChecked={sp.visible === "1"} /> Visible</label>
          <label className="flex items-center gap-1"><input type="checkbox" name="removed" value="1" defaultChecked={sp.removed === "1"} /> Removed</label>
        </div>
        <button className="btn-primary py-1.5 text-xs">Filter</button>
      </form>

      <p className="text-xs text-slate-500">
        {filtered.length} of {rows.length} plans · rule: +{rules.markupPercent}%{rules.markupFixedCents ? ` + ${money(rules.markupFixedCents)}` : ""}, rounding {rules.rounding}, setup {rules.setupPolicy} · offered regions: {[...enabledRegions].join(", ") || "none"}
      </p>

      {filtered.length === 0 ? (
        <EmptyState title="No plans match" sub={rows.length ? "Loosen the filters." : "Run a sync to load the catalogue."} />
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="w-full min-w-[1100px] text-left text-xs">
            <thead className="border-b border-white/[0.06] text-[11px] uppercase tracking-wider text-slate-500">
              <tr>
