                <th className="px-3 py-2 text-right">Our cost</th>
                <th className="px-3 py-2 text-right">Nxeon</th>
                <th className="px-3 py-2 text-right">Margin</th>
                <th className="px-3 py-2 text-right">Setup</th>
                <th className="px-3 py-2">Shown</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/[0.04]">
              {filtered.map(({ it, regions, p, maxRam }) => (
                <tr key={it.id} className={`hover:bg-white/[0.02] ${it.removedAt ? "opacity-50" : ""}`}>
                  <td className="px-3 py-2">
                    <Link href={`/admin/dedicated/catalog/${it.id}`} className="font-semibold text-slate-100 hover:text-white">{it.name}</Link>
                    <div className="font-mono text-[10px] text-slate-500">{it.planCode} · {it.range}</div>
                    {it.priceChangedAt && it.previousMonthlyCents != null && <div className="text-[10px] text-amber-300">was {money(it.previousMonthlyCents)}</div>}
                  </td>
                  <td className="px-3 py-2">
                    <div className="text-slate-200">{it.cpuBrand} {it.cpuModel}</div>
                    <div className="text-[10px] text-slate-500">{it.cpuCores}c/{it.cpuThreads}t{it.cpuFrequencyGhz ? ` · ${it.cpuFrequencyGhz}${it.cpuBoostGhz ? `-${it.cpuBoostGhz}` : ""} GHz` : ""}</div>
                  </td>
                  <td className="px-3 py-2 text-slate-200">{it.defaultRamGb ?? "?"} GB{maxRam > (it.defaultRamGb ?? 0) && <span className="text-[10px] text-slate-500"> (to {maxRam})</span>}</td>
                  <td className="max-w-[220px] px-3 py-2 text-slate-300"><span className="line-clamp-2">{it.defaultStorage ?? "—"}</span></td>
                  <td className="px-3 py-2">
                    <div className="flex max-w-[280px] flex-wrap gap-1">
                      {regions.map((r) => (
                        <span key={r.code} title={`${r.label} [${r.dcs.join(",")}] ${r.stock ? stockLabel(r.stock) : "no stock data"}${r.offered ? "" : " · not offered"}${r.hidden ? " · hidden for this item" : ""}`}
                          className={`flex items-center gap-1 rounded border px-1.5 py-0.5 text-[10px] ${r.offered ? "border-white/10 text-slate-200" : "border-dashed border-white/10 text-slate-500"} ${r.hidden ? "line-through" : ""}`}>
                          <span className={`h-1.5 w-1.5 rounded-full ${STOCK_TONE(r.stock)}`} />
