                  <td className={`px-3 py-2 text-right font-mono ${p.margin.cents < 0 ? "text-red-300" : "text-emerald-300"}`}>{money(p.margin.cents, it.currency)}<div className="text-[10px] text-slate-500">{p.margin.percent ?? "-"}%</div></td>
                  <td className="px-3 py-2 text-right font-mono text-[11px] text-slate-400">{money(p.costSetup)} → {money(p.sellSetup)}</td>
