import { PageHeader, Badge } from "@/components/ui/primitives";
import { ItemControlsForm } from "@/components/admin/dedicated/Controls";
import { defaultConfig, itemRegions, loadAvailability, loadRules, priceView, stockByDc, tierFor } from "@/lib/dedicated/catalog-view";
import { firstYearMargin, money, sellMonthlyCents, setupPaybackMonths } from "@/lib/dedicated/pricing";
import { stockLabel, stockRank } from "@/lib/dedicated/ovh-catalog";
import { regionForDc } from "@/lib/dedicated/regions";
import { dedicatedOfferPrefill, offerComposerHref, offersAvailable } from "@/lib/dedicated/offer-link";

export const dynamic = "force-dynamic";

type Term = { mode: string; months: number; termCents: number; setupCents: number };
type Promo = { name: string; description: string; endDate: string | null; appliesTo: string };

const STOCK_CELL = (code: string | undefined) =>
  !code ? "text-slate-600" : /^1H/.test(code) ? "text-cyan-300" : /^\d+H/.test(code) ? "text-brand-300" : code === "comingSoon" ? "text-amber-300" : "text-slate-500";

/** ADMIN-ONLY: one upstream catalogue plan with every option, live stock matrix and Nxeon controls. */
export default async function AdminDedicatedItem({ params }: { params: Promise<{ id: string }> }) {
  await requireAdmin();
  const { id } = await params;
  const it = await db.dedicatedCatalogItem.findUnique({ where: { id }, include: { options: { orderBy: [{ family: "asc" }, { monthlyCents: "asc" }] } } });
  if (!it) notFound();
  const { rules, enabledRegions } = await loadRules();
  const rows = (await loadAvailability([it.planCode])).get(it.planCode) ?? [];
  const def = defaultConfig(it.options);
  const regions = itemRegions(it.datacenters, stockByDc(rows, def), enabledRegions, it.hiddenRegions);
  const p = priceView(it, rules);
  const fy = firstYearMargin({ monthlyCost: p.costMonthly, monthlySell: p.sellMonthly, setupCost: p.costSetup, setupSell: p.sellSetup });
  const payback = setupPaybackMonths({ monthlyCost: p.costMonthly, monthlySell: p.sellMonthly, setupCost: p.costSetup, setupSell: p.sellSetup });
  const optSell = (cost: number) => (cost > 0 ? sellMonthlyCents(0, { ...rules, markupFixedCents: 0, rounding: "none" }, { markupPercent: it.markupPercent }, cost) : 0);
  const terms = (it.terms as unknown as Term[]) ?? [];
  const promos = (it.promotions as unknown as Promo[]) ?? [];
  const live = it.options.filter((o) => !o.removedAt);
  const families = Array.from(new Set(live.map((o) => o.family)));

  // Stock matrix: memory x storage configurations vs datacenters.
  const dcs = Array.from(new Set(rows.map((r) => r.datacenter))).sort();
  const configs = new Map<string, Map<string, string>>();
  for (const r of rows) {
    const k = `${r.memory ?? "-"} | ${r.storage ?? "-"}`;
    const m = configs.get(k) ?? new Map<string, string>();
    const prev = m.get(r.datacenter);
    if (!prev || stockRank(r.availability) < stockRank(prev)) m.set(r.datacenter, r.availability);
    configs.set(k, m);
  }
  const labelOf = (product: string) => live.find((o) => o.productCode === product)?.label ?? product;
  const fetchedAt = rows.length ? await db.dedicatedAvailability.findFirst({ where: { planCode: it.planCode }, select: { fetchedAt: true } }) : null;

  const mainRegion = regions.find((r) => r.offered && r.inStock) ?? regions.find((r) => r.offered) ?? regions[0];
  const ram = live.find((o) => o.family === "memory" && o.isDefault);
  const disk = live.find((o) => o.family === "storage" && o.isDefault);
  const bw = live.find((o) => o.family === "bandwidth" && o.isDefault);
  const prefill = dedicatedOfferPrefill({
    itemId: it.id,
    customerName: it.displayName || `${tierFor(it.range).tier} ${it.cpuModel}`,
    cpuLabel: `${it.cpuBrand} ${it.cpuModel}`,
    cores: it.cpuCores * it.cpuCount,
    ramGb: it.defaultRamGb,
    storageGb: disk?.storageGb ?? null,
    storageLabel: it.defaultStorage,
    trafficTb: bw?.trafficTb ?? null,
    region: mainRegion?.code ?? "",
    sellMonthlyCents: p.sellMonthly,
    sellSetupCents: p.sellSetup,
    upstreamPlanCode: it.planCode,
    upstreamDatacenter: mainRegion?.dcs[0] ?? null,
  });
  const canOffer = offersAvailable();

  return (
    <div className="space-y-6">
      <PageHeader title={<>{it.name} <span className="text-base font-normal text-slate-400">{it.invoiceName.split("|")[1] ?? ""}</span></>} sub={`${it.planCode} · ${it.range} · ${it.catalog} catalogue · subsidiary ${it.subsidiary}`}>
        <Link href="/admin/dedicated" className="btn-ghost py-1.5 text-xs">Back to catalogue</Link>
        <Link href={`/admin/preview/dedicated?item=${it.id}`} className="btn-ghost py-1.5 text-xs">Preview as customer</Link>
        {canOffer ? (
          <Link href={offerComposerHref(prefill)} className="btn-primary py-1.5 text-xs">Create offer from this item</Link>
        ) : (
          <button type="button" disabled className="btn-primary py-1.5 text-xs" title="Needs the custom-offers feature (branch feature/chat-offers) merged — the prefill is ready.">Create offer (needs offers feature)</button>
        )}
      </PageHeader>

      {it.removedAt && <div className="card border-amber-500/30 p-3 text-xs text-amber-200">Removed from the upstream catalogue on {it.removedAt.toISOString().slice(0, 10)}. Kept for history and existing customers.</div>}

      <div className="grid gap-4 lg:grid-cols-3">
        <div className="card space-y-3 p-5 lg:col-span-2">
          <h3 className="text-sm font-semibold">Hardware</h3>
          <dl className="grid gap-3 text-sm sm:grid-cols-3">
            <div><dt className="text-[11px] text-slate-500">CPU</dt><dd>{it.cpuCount > 1 ? `${it.cpuCount}x ` : ""}{it.cpuBrand} {it.cpuModel}</dd></div>
            <div><dt className="text-[11px] text-slate-500">Cores / threads</dt><dd>{it.cpuCores * it.cpuCount} / {it.cpuThreads * it.cpuCount}</dd></div>
            <div><dt className="text-[11px] text-slate-500">Clock</dt><dd>{it.cpuFrequencyGhz ?? "?"} GHz{it.cpuBoostGhz ? ` (boost ${it.cpuBoostGhz})` : ""}</dd></div>
            <div><dt className="text-[11px] text-slate-500">Default RAM</dt><dd>{it.defaultRamGb ?? "?"} GB</dd></div>
            <div className="sm:col-span-2"><dt className="text-[11px] text-slate-500">Default storage</dt><dd>{it.defaultStorage ?? "—"}</dd></div>
            <div><dt className="text-[11px] text-slate-500">Bandwidth</dt><dd>{it.defaultBandwidthMbps ? `${it.defaultBandwidthMbps} Mbps` : "—"}</dd></div>
            <div><dt className="text-[11px] text-slate-500">Upstream SLA / anti-DDoS</dt><dd>{it.slaPercent ?? "?"}% · {it.antiDdos ?? "?"}</dd></div>
            <div><dt className="text-[11px] text-slate-500">Release year</dt><dd>{it.releaseYear ?? "?"}</dd></div>
            <div><dt className="text-[11px] text-slate-500">Customer tier</dt><dd>{tierFor(it.range).tier}</dd></div>
            <div><dt className="text-[11px] text-slate-500">First / last seen</dt><dd className="text-xs">{it.firstSeenAt.toISOString().slice(0, 10)} / {it.lastSeenAt.toISOString().slice(0, 16).replace("T", " ")}</dd></div>
          </dl>
        </div>
        <div className="card space-y-2 p-5 text-sm">
          <h3 className="text-sm font-semibold">Economics (default build)</h3>
          <div className="flex justify-between"><span className="text-slate-400">Our cost /mo</span><span className="font-mono">{money(p.costMonthly, it.currency)}</span></div>
          <div className="flex justify-between"><span className="text-slate-400">Nxeon price /mo</span><span className="font-mono text-white">{money(p.sellMonthly, it.currency)}</span></div>
          <div className="flex justify-between"><span className="text-slate-400">Monthly margin</span><span className={`font-mono ${p.margin.cents < 0 ? "text-red-300" : "text-emerald-300"}`}>{money(p.margin.cents)} ({p.margin.percent ?? "-"}%)</span></div>
          <div className="flex justify-between"><span className="text-slate-400">Setup cost → charged</span><span className="font-mono">{money(p.costSetup)} → {money(p.sellSetup)}</span></div>
          {it.promoSetupCents != null && <div className="text-[11px] text-amber-300">List setup {money(it.setupCents)}; a live upstream promotion lowers our cost.</div>}
          <div className="flex justify-between"><span className="text-slate-400">First-year margin</span><span className="font-mono">{money(fy.cents)} ({fy.percent ?? "-"}%)</span></div>
          <div className="flex justify-between"><span className="text-slate-400">Absorbed setup paid back</span><span className="font-mono">{payback === 0 ? "n/a" : payback == null ? "never" : `${payback} mo`}</span></div>
          {terms.length > 0 && (
            <div className="pt-2">
              <div className="text-[11px] uppercase tracking-wider text-slate-500">Upstream commitment terms</div>
              {terms.map((t) => (
                <div key={t.mode} className="flex justify-between text-xs"><span className="text-slate-400">{t.mode} ({t.months} mo)</span><span className="font-mono">{money(t.termCents)} = {money(Math.round(t.termCents / t.months))}/mo · setup {money(t.setupCents)}</span></div>
              ))}
            </div>
          )}
          {promos.map((pr) => <div key={pr.name} className="text-[11px] text-amber-300">Promo {pr.name} ({pr.appliesTo}): {pr.description}{pr.endDate ? ` until ${pr.endDate.slice(0, 10)}` : ""}</div>)}
        </div>
      </div>

      <div className="card p-5">
        <h3 className="text-sm font-semibold">Regions</h3>
        <div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
          {regions.map((r) => (
            <div key={r.code} className="rounded-lg border border-white/[0.06] p-3 text-xs">
              <div className="flex items-center justify-between"><b>{r.label}</b><span className="font-mono text-slate-500">{r.code}</span></div>
              <div className="mt-1 text-slate-400">upstream: {r.dcs.join(", ")}</div>
              <div className={`mt-1 ${STOCK_CELL(r.stock)}`}>{r.stock ? stockLabel(r.stock) : "no stock data"}</div>
              <div className="mt-1 flex gap-1">
                {r.offered ? <Badge tone="green">offered</Badge> : <Badge tone="amber">not offered</Badge>}
                {!r.sold && <Badge tone="slate">no Nxeon nodes</Badge>}
                {r.hidden && <Badge tone="red">hidden here</Badge>}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="card overflow-x-auto p-5">
        <h3 className="text-sm font-semibold">Live stock by configuration</h3>
        <p className="mt-1 text-[11px] text-slate-500">{rows.length} rows{fetchedAt ? ` · fetched ${fetchedAt.fetchedAt.toISOString().slice(0, 16).replace("T", " ")} UTC` : ""} · default build is bold.</p>
        {rows.length === 0 ? <p className="mt-2 text-xs text-slate-400">No stock data for this plan.</p> : (
          <table className="mt-3 w-full min-w-[700px] text-left text-[11px]">
            <thead className="text-slate-500"><tr><th className="py-1 pr-3">Memory | storage</th>{dcs.map((d) => <th key={d} className="px-2 py-1">{d}<div className="font-normal text-slate-600">{regionForDc(d).code}</div></th>)}</tr></thead>
            <tbody className="divide-y divide-white/[0.04]">
              {[...configs.entries()].map(([k, m]) => {
                const [mem, st] = k.split(" | ");
                const isDef = mem === def.memory && st === def.storage;
                return (
                  <tr key={k} className={isDef ? "font-semibold" : ""}>
                    <td className="py-1 pr-3 text-slate-300">{labelOf(mem)} | {labelOf(st)}</td>
                    {dcs.map((d) => <td key={d} className={`px-2 py-1 ${STOCK_CELL(m.get(d))}`}>{m.get(d) ?? "—"}</td>)}
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        <div className="card overflow-x-auto p-5">
          <h3 className="text-sm font-semibold">Options</h3>
          {families.map((fam) => (
            <div key={fam} className="mt-3">
              <div className="text-[11px] uppercase tracking-wider text-slate-500">{fam}</div>
              <table className="mt-1 w-full text-left text-[11px]">
                <tbody className="divide-y divide-white/[0.04]">
                  {live.filter((o) => o.family === fam).map((o) => (
                    <tr key={o.id} className={o.isDefault ? "font-semibold" : ""}>
                      <td className="py-1 pr-2">{o.label}{o.isDefault && <span className="ml-1 text-[10px] text-cyan-300">default</span>}<div className="font-mono text-[10px] font-normal text-slate-600">{o.planCode}</div></td>
                      <td className="py-1 pr-2 text-right font-mono text-slate-400">+{money(o.monthlyCents)}</td>
                      <td className="py-1 text-right font-mono text-slate-100">+{money(optSell(o.monthlyCents))}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ))}
          <p className="mt-3 text-[10px] text-slate-500">Columns: upstream extra cost /mo, Nxeon extra price /mo (item markup %, no rounding).</p>
        </div>
        <ItemControlsForm
          itemId={it.id}
          visible={it.visible}
          displayName={it.displayName}
          markupPercent={it.markupPercent}
          markupFixedCents={it.markupFixedCents}
          overrideMonthlyCents={it.overrideMonthlyCents}
          setupPolicy={it.setupPolicy}
          setupCustomCents={it.setupCustomCents}
          hiddenRegions={it.hiddenRegions}
          adminNote={it.adminNote}
          regions={regions.map((r) => ({ code: r.code, label: r.label }))}
        />
      </div>
      {!canOffer && (
        <div className="card p-4 text-[11px] text-slate-400">
          <b className="text-slate-200">Offer prefill (ready for when custom offers merge):</b> kind {prefill.kind}, {prefill.cpuCores} cores, {prefill.ramMB / 1024} GB RAM, {prefill.diskGB} GB {prefill.storageTier}, region {prefill.region || "—"}, {money(prefill.renewalMonthlyCents)}/mo, setup {money(prefill.setupFeeCents)}. Internal note: {prefill.internalNote}
          {ram ? "" : ""}
        </div>
      )}
    </div>
  );
}

