          {promos.map((pr) => <div key={pr.name} className="text-[11px] text-amber-300">Promo {pr.name} ({pr.appliesTo}): {pr.description}{pr.endDate ? ` until ${pr.endDate.slice(0, 10)}` : ""}</div>)}
