import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader } from "@/components/ui/primitives";
import { PricingRulesForm, PublicFlagToggle } from "@/components/admin/dedicated/Controls";
import { loadRules, priceView } from "@/lib/dedicated/catalog-view";
import { DEDICATED_DC_REGIONS, regionForDc } from "@/lib/dedicated/regions";
import { money } from "@/lib/dedicated/pricing";
import { dedicatedPublicEnabled } from "@/lib/dedicated/gate";

export const dynamic = "force-dynamic";

/** ADMIN-ONLY: dedicated pricing rules, regions offered, the public-pages switch, and a worked example. */
export default async function AdminDedicatedPricing() {
  await requireAdmin();
  const [{ rules, enabledRegions, settings }, publicOn, items, nodes] = await Promise.all([
    loadRules(),
    dedicatedPublicEnabled(),
    db.dedicatedCatalogItem.findMany({ where: { removedAt: null }, select: { id: true, name: true, planCode: true, datacenters: true, monthlyCents: true, setupCents: true, promoSetupCents: true, markupPercent: true, markupFixedCents: true, overrideMonthlyCents: true, setupPolicy: true, setupCustomCents: true }, orderBy: { monthlyCents: "asc" } }).catch(() => []),
    db.node.findMany({ select: { region: true } }).catch(() => []),
  ]);
  const nodeRegions = new Set(nodes.map((n) => n.region));
  const plansPerRegion = new Map<string, number>();
  for (const it of items) for (const code of new Set(it.datacenters.map((d) => regionForDc(d).code))) plansPerRegion.set(code, (plansPerRegion.get(code) ?? 0) + 1);
  const regions = Array.from(new Map(Object.values(DEDICATED_DC_REGIONS).map((r) => [r.code, r])).values()).map((r) => ({
    code: r.code, label: r.label, sold: r.sold || nodeRegions.has(r.code), plans: plansPerRegion.get(r.code) ?? 0,
  }));
  const sample = items.length ? [items[0], items[Math.floor(items.length / 4)], items[Math.floor(items.length / 2)], items[Math.floor((items.length * 3) / 4)], items[items.length - 1]] : [];

  return (
    <div className="space-y-6">
      <PageHeader title="Dedicated pricing" sub="Global markup, rounding, setup-fee policy and offered regions. Per-item overrides live on each catalogue item." />
      <PublicFlagToggle on={publicOn} />
      <PricingRulesForm
        markupPercent={rules.markupPercent}
        markupFixedCents={rules.markupFixedCents}
        rounding={rules.rounding}
        setupPolicy={rules.setupPolicy}
        setupCustomCents={rules.setupCustomCents}
        enabledRegions={[...enabledRegions]}
        regions={regions}
        syncEnabled={settings.dedicated_catalog_sync_enabled !== "false"}
        syncHours={Number(settings.dedicated_catalog_sync_hours) || 6}
      />
      {sample.length > 0 && (
        <div className="card overflow-x-auto p-5">
          <h3 className="text-sm font-semibold">What the current rule produces</h3>
          <table className="mt-3 w-full min-w-[640px] text-left text-xs">
            <thead className="text-[11px] uppercase tracking-wider text-slate-500"><tr><th className="py-1">Plan</th><th className="text-right">Cost /mo</th><th className="text-right">Nxeon /mo</th><th className="text-right">Margin</th><th className="text-right">Setup cost → charged</th></tr></thead>
            <tbody className="divide-y divide-white/[0.04]">
              {sample.map((it) => {
                const p = priceView(it, rules);
                return (
                  <tr key={it.id}>
                    <td className="py-1.5">{it.name} <span className="font-mono text-[10px] text-slate-500">{it.planCode}</span></td>
                    <td className="text-right font-mono text-slate-400">{money(p.costMonthly)}</td>
                    <td className="text-right font-mono">{money(p.sellMonthly)}</td>
                    <td className="text-right font-mono text-emerald-300">{money(p.margin.cents)} ({p.margin.percent ?? "-"}%)</td>
                    <td className="text-right font-mono text-slate-400">{money(p.costSetup)} → {money(p.sellSetup)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
      <p className="text-[11px] text-slate-500">Prices are in the synced subsidiary currency (USD for WE). Cost, margin and upstream codes are shown in admin only; customers see the Nxeon price.</p>
    </div>
  );
}
EOF
