import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, Badge, EmptyState } from "@/components/ui/primitives";
import { DedicatedServerFormView } from "@/components/admin/dedicated/Controls";
import { DEDICATED_DC_REGIONS } from "@/lib/dedicated/regions";
import { money } from "@/lib/dedicated/pricing";

export const dynamic = "force-dynamic";

export const STATUS_TONE: Record<string, "brand" | "green" | "red" | "amber" | "slate"> = { PENDING: "slate", PROVISIONING: "brand", ACTIVE: "green", SUSPENDED: "amber", CANCELLED: "red" };

/** ADMIN-ONLY: customer dedicated machines we manage by hand. */
export default async function AdminDedicatedServers({ searchParams }: { searchParams: Promise<{ status?: string; item?: string }> }) {
  await requireAdmin();
  const sp = await searchParams;
  const rows = await db.dedicatedServer.findMany({
    where: sp.status ? { status: sp.status as "ACTIVE" } : {},
    include: { requests: { where: { status: "OPEN" }, select: { id: true } } },
    orderBy: { createdAt: "desc" },
    take: 300,
  }).catch(() => null);
  if (rows === null) return <div className="space-y-6"><PageHeader title="Managed dedicated servers" /><EmptyState title="Tables not migrated" sub="Run prisma db push on this database first." /></div>;
  const users = new Map((await db.user.findMany({ where: { id: { in: rows.map((r) => r.userId) } }, select: { id: true, email: true } })).map((u) => [u.id, u.email]));
  const regions = Array.from(new Map(Object.values(DEDICATED_DC_REGIONS).map((r) => [r.code, { code: r.code, label: r.label }])).values());
  const item = sp.item ? await db.dedicatedCatalogItem.findUnique({ where: { id: sp.item } }) : null;
  const mrr = rows.filter((r) => r.status === "ACTIVE").reduce((a, r) => a + (r.renewalMonthlyCents ?? 0), 0);
  const cost = rows.filter((r) => r.status === "ACTIVE").reduce((a, r) => a + (r.costMonthlyCents ?? 0), 0);

  return (
    <div className="space-y-6">
      <PageHeader title="Managed dedicated servers" sub={`${rows.length} machines · active MRR ${money(mrr)} · our cost ${money(cost)}`}>
        {["", "PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED", "CANCELLED"].map((s) => (
          <Link key={s || "all"} href={s ? `/admin/dedicated/servers?status=${s}` : "/admin/dedicated/servers"} className={`btn-ghost py-1 text-xs ${sp.status === s || (!sp.status && !s) ? "text-white" : "text-slate-400"}`}>{s || "All"}</Link>
        ))}
      </PageHeader>
      {rows.length === 0 ? <EmptyState title="No dedicated servers yet" sub="Add one below once a customer's machine is ordered." /> : (
        <div className="card overflow-x-auto p-0">
          <table className="w-full min-w-[900px] text-left text-xs">
            <thead className="border-b border-white/[0.06] text-[11px] uppercase tracking-wider text-slate-500">
              <tr><th className="px-3 py-2">Server</th><th className="px-3 py-2">Customer</th><th className="px-3 py-2">Specs</th><th className="px-3 py-2">Region</th><th className="px-3 py-2">Upstream service</th><th className="px-3 py-2">Status</th><th className="px-3 py-2 text-right">Price / cost</th><th className="px-3 py-2">Renews</th></tr>
            </thead>
            <tbody className="divide-y divide-white/[0.04]">
              {rows.map((r) => (
                <tr key={r.id} className="hover:bg-white/[0.02]">
                  <td className="px-3 py-2"><Link href={`/admin/dedicated/servers/${r.id}`} className="font-semibold text-slate-100 hover:text-white">{r.label}</Link><div className="text-[10px] text-slate-500">{r.ipv4[0] ?? "no IP"}{r.requests.length ? ` · ${r.requests.length} open request(s)` : ""}</div></td>
                  <td className="px-3 py-2 text-slate-300">{users.get(r.userId) ?? r.userId}</td>
                  <td className="px-3 py-2 text-slate-300">{r.cpu} · {r.ramGb} GB</td>
                  <td className="px-3 py-2 font-mono text-slate-400">{r.region}{r.datacenter ? ` (${r.datacenter})` : ""}</td>
                  <td className="px-3 py-2 font-mono text-[10px] text-slate-500">{r.providerServiceName ?? "—"}</td>
                  <td className="px-3 py-2"><Badge tone={STATUS_TONE[r.status]}>{r.status}</Badge></td>
                  <td className="px-3 py-2 text-right font-mono">{r.renewalMonthlyCents != null ? money(r.renewalMonthlyCents) : "—"}<div className="text-[10px] text-slate-500">{r.costMonthlyCents != null ? money(r.costMonthlyCents) : "—"}</div></td>
                  <td className="px-3 py-2 text-slate-400">{r.renewalDate?.toISOString().slice(0, 10) ?? "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      <DedicatedServerFormView regions={regions} initial={item ? {
        catalogItemId: item.id, cpu: `${item.cpuBrand} ${item.cpuModel}`, cores: item.cpuCores * item.cpuCount, threads: item.cpuThreads * item.cpuCount,
        ramGb: item.defaultRamGb ?? 0, storage: item.defaultStorage ?? "", bandwidth: item.defaultBandwidthMbps ? `${item.defaultBandwidthMbps >= 1000 ? item.defaultBandwidthMbps / 1000 + " Gbps" : item.defaultBandwidthMbps + " Mbps"} public bandwidth` : "",
        costMonthly: (item.monthlyCents / 100).toFixed(2),
      } : undefined} />
    </div>
  );
}
