import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { dedicatedPublicEnabled } from "@/lib/dedicated/gate";
import { loadPublicCatalog } from "@/lib/dedicated/public-catalog";
import { DedicatedMarketing } from "@/components/dedicated/DedicatedMarketing";
import { PreviewBar } from "./PreviewBar";

export const dynamic = "force-dynamic";

/**
 * ADMIN-ONLY preview of the public /dedicated-servers page, rendered with the
 * exact customer component and the real catalogue + pricing rules. When no item
 * has been opted in yet (or ?all=1), every live item in an offered region is
 * shown so the design can be reviewed before the owner curates the list.
 */
export default async function PreviewDedicatedPublic({ searchParams }: { searchParams: Promise<{ all?: string }> }) {
  await requireAdmin();
  const sp = await searchParams;
  const visibleCount = await db.dedicatedCatalogItem.count({ where: { visible: true, removedAt: null } }).catch(() => 0);
  const previewAll = sp.all === "1" || visibleCount === 0;
  const [entries, on] = await Promise.all([loadPublicCatalog({ previewAll }), dedicatedPublicEnabled()]);
  return (
    <div>
      <PreviewBar on={on} current="public" note={previewAll ? `Showing ALL ${entries.length} builds in offered regions (${visibleCount} opted in) — the live page lists only items marked visible.` : `Showing the ${entries.length} builds customers would see.`} />
      <div className="-mx-4 overflow-hidden rounded-2xl border border-white/[0.06] sm:mx-0">
        <DedicatedMarketing entries={entries} requestHref="#preview-request?topic=dedicated" />
      </div>
    </div>
  );
}
