import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import {
  parseCatalog,
  parseAvailability,
  priceToCents,
  isInStock,
  stockRank,
  stockLabel,
  catalogUrl,
  availabilityUrl,
  apiHostFor,
  publicGet,
  guessRange,
} from "../lib/dedicated/ovh-catalog.ts";
import { plausibleReplacement, syncDue, summarise, feedFor, itemHash } from "../lib/dedicated/sync.ts";
import { stockByDc, itemRegions, defaultConfig } from "../lib/dedicated/catalog-view.ts";

/**
 * Dedicated catalogue parsing against RECORDED upstream responses
 * (test/fixtures/dedicated/*.json — trimmed copies of the live public catalogue
 * and stock feed captured 2026-10-06; public data, no credentials). Pure: no
 * network, no DB.
 */
const fx = (n: string) => JSON.parse(readFileSync(path.resolve(__dirname, "fixtures/dedicated", n), "utf8"));
const eco = parseCatalog(fx("eco-WE.json"), "eco");
const bm = parseCatalog(fx("baremetalServers-WE.json"), "baremetalServers");
const byCode = (code: string) => [...eco.items, ...bm.items].find((i) => i.planCode === code)!;

test("upstream price unit (1e-8) converts to integer cents", () => {
  assert.equal(priceToCents(10700000000), 10700);
  assert.equal(priceToCents(4960000000), 4960);
  assert.equal(priceToCents(0), 0);
  assert.equal(priceToCents(undefined), 0);
  assert.equal(priceToCents("12"), 0);
});

test("eco catalogue: locale, plan count and every range parse", () => {
  assert.equal(eco.subsidiary, "WE");
  assert.equal(eco.currency, "USD");
  assert.equal(eco.items.length, 4);
  assert.deepEqual(new Set(eco.items.map((i) => i.range)), new Set(["advance", "rise", "kimsufi"]));
  assert.deepEqual(new Set(bm.items.map((i) => i.range)), new Set(["game", "scale"]));
});

test("a plan's CPU, base price, setup fee and datacenters come straight from the feed", () => {
  const adv = byCode("24adv01-v3");
  assert.equal(adv.name, "ADVANCE-1");
  assert.equal(adv.cpuBrand, "AMD");
  assert.equal(adv.cpuModel, "EPYC 4244P");
  assert.equal(adv.cpuCores, 6);
  assert.equal(adv.cpuThreads, 12);
  assert.equal(adv.cpuFrequencyGhz, 3.8);
  assert.equal(adv.monthlyCents, 10700);
  assert.equal(adv.setupCents, 10700);
  assert.deepEqual(adv.datacenters, ["fra", "gra", "lon", "rbx", "sbg", "waw", "bhs"]);
  // the APAC variant is its own plan with its own (higher) price
  const sgp = byCode("24adv01-v3-sgp");
  assert.deepEqual(sgp.datacenters, ["sgp"]);
  assert.ok(sgp.monthlyCents > adv.monthlyCents);
});

test("commitment terms are parsed (monthly, 12 and 24 months)", () => {
  const adv = byCode("24adv01-v3");
  assert.deepEqual(adv.terms.map((t) => t.months), [1, 12, 24]);
  assert.equal(adv.terms[1].termCents, 121980);
  assert.equal(adv.terms[1].setupCents, 0);
});

test("options: memory/storage/bandwidth families with defaults and extra cost", () => {
  const adv = byCode("24adv01-v3");
  const mem = adv.options.filter((o) => o.family === "memory");
  assert.ok(mem.length >= 3);
  const def = mem.find((o) => o.isDefault)!;
  assert.equal(def.ramGb, 32);
  assert.equal(def.monthlyCents, 0);
  assert.equal(adv.defaultRamGb, 32);
  const ram64 = mem.find((o) => o.ramGb === 64)!;
  assert.equal(ram64.monthlyCents, 4960);
  assert.match(ram64.label, /^64 GB DDR5/);
  const disk = adv.options.find((o) => o.family === "storage" && o.isDefault)!;
  assert.equal(disk.storageGb, 1920);
  assert.match(adv.defaultStorage ?? "", /2x 960GB NVMe/);
  assert.ok(adv.options.some((o) => o.family === "bandwidth" && o.bandwidthMbps === 3000));
  // licences (windows/sql/cpanel) are never resold as options
  assert.ok(adv.options.every((o) => ["memory", "storage", "system-storage", "bandwidth", "vrack", "gpu"].includes(o.family)));
});

test("a live setup-fee promotion is captured (free setup on the game range)", () => {
  const g = byCode("26game01-v4");
  assert.equal(g.range, "game");
  assert.ok(g.setupCents > 0);
  assert.equal(g.promoSetupCents, 0);
  assert.ok(g.promotions.some((p) => p.appliesTo === "setup" && p.endDate));
});

test("shape drift: a plan with no server spec or no monthly price is skipped with a warning, not a crash", () => {
  const raw = fx("eco-WE.json");
  raw.plans.push({ planCode: "weird-1", product: "does-not-exist", pricings: [], addonFamilies: [] });
  const r = parseCatalog(raw, "eco");
  assert.equal(r.items.length, 4);
  assert.ok(r.warnings.some((w) => w.startsWith("weird-1")));
  assert.throws(() => parseCatalog({ nope: true }, "eco"), /no plans/);
  assert.throws(() => parseCatalog(null, "eco"), /no plans/);
});

test("availability feed: rows per datacenter, filtered to plans we hold", () => {
  const raw = fx("availability-ca.json");
  const all = parseAvailability(raw);
  assert.ok(all.length > 100);
  const only = parseAvailability(raw, new Set(["26game01-v4"]));
  assert.ok(only.length > 0 && only.every((r) => r.planCode === "26game01-v4"));
  assert.ok(only.every((r) => r.memory && r.storage && r.datacenter));
  assert.throws(() => parseAvailability({}), /not an array/);
});

test("stock codes: in-stock detection, ranking and labels", () => {
  assert.equal(isInStock("1H-high"), true);
  assert.equal(isInStock("72H"), true);
  assert.equal(isInStock("unavailable"), false);
  assert.equal(isInStock("comingSoon"), false);
  assert.ok(stockRank("1H-high") < stockRank("1H-low"));
  assert.ok(stockRank("1H-low") < stockRank("72H"));
  assert.ok(stockRank("72H") < stockRank("comingSoon"));
  assert.ok(stockRank("comingSoon") < stockRank("unavailable"));
  assert.equal(stockLabel("72H"), "within 3 days");
  assert.equal(stockLabel("1H-low"), "within 1 hour (low stock)");
});

test("stockByDc picks the best state per datacenter, optionally for the default build only", () => {
  const rows = [
    { planCode: "p", memory: "m1", storage: "s1", datacenter: "sgp", availability: "unavailable" },
    { planCode: "p", memory: "m2", storage: "s1", datacenter: "sgp", availability: "72H" },
    { planCode: "p", memory: "m1", storage: "s1", datacenter: "bhs", availability: "1H-low" },
  ];
  assert.equal(stockByDc(rows).get("sgp"), "72H");
  assert.equal(stockByDc(rows, { memory: "m1", storage: "s1" }).get("sgp"), "unavailable");
  const regions = itemRegions(["sgp", "bhs", "gra"], stockByDc(rows), new Set(["sgp1"]), ["bhs1"]);
  const sgp = regions.find((r) => r.code === "sgp1")!;
  assert.equal(sgp.offered, true);
  assert.equal(sgp.inStock, true);
  assert.equal(regions.find((r) => r.code === "bhs1")!.hidden, true);
  assert.equal(regions.find((r) => r.code === "gra1")!.stock, "");
});

test("defaultConfig reads the default memory/storage product codes", () => {
  const adv = byCode("24adv01-v3");
  const d = defaultConfig(adv.options.map((o) => ({ ...o, removedAt: null })));
  assert.equal(d.memory, "ram-32g-on-die-ecc-5200");
  assert.match(d.storage ?? "", /^softraid-2x960nvme/);
});

test("keep-last-good: an implausibly small result never replaces a big catalogue", () => {
  assert.equal(plausibleReplacement(0, 0), false);
  assert.equal(plausibleReplacement(5, 0), true);
  assert.equal(plausibleReplacement(5, 8), true);
  assert.equal(plausibleReplacement(20, 165), false);
  assert.equal(plausibleReplacement(60, 165), true);
});

test("syncDue: request wins, disabled stops the schedule, interval respected", () => {
  const now = new Date("2026-10-06T12:00:00Z");
  const h = (n: number) => new Date(now.getTime() - n * 3_600_000);
  assert.equal(syncDue({ enabled: false, lastStartedAt: h(100), intervalHours: 6, requested: true, now }), true);
  assert.equal(syncDue({ enabled: false, lastStartedAt: h(100), intervalHours: 6, requested: false, now }), false);
  assert.equal(syncDue({ enabled: true, lastStartedAt: null, intervalHours: 6, requested: false, now }), true);
  assert.equal(syncDue({ enabled: true, lastStartedAt: h(5), intervalHours: 6, requested: false, now }), false);
  assert.equal(syncDue({ enabled: true, lastStartedAt: h(6), intervalHours: 6, requested: false, now }), true);
  assert.equal(syncDue({ enabled: true, lastStartedAt: h(7), intervalHours: NaN, requested: false, now }), true);
});

test("summarise counts plans per range and flags unmapped datacenters", () => {
  const s = summarise([eco, bm]);
  assert.equal(s.totalPlans, 6);
  assert.equal(s.catalogs.eco.ranges.advance, 2);
  assert.ok(s.catalogs.eco.datacenters.sgp >= 1);
  assert.deepEqual(s.unmappedDcs, []);
  const weird = { ...eco, items: [{ ...eco.items[0], datacenters: ["xyz"] }] };
  assert.deepEqual(summarise([weird]).unmappedDcs, ["xyz"]);
});

test("item hash is stable and changes with the price", () => {
  const a = byCode("24sk202");
  assert.equal(itemHash(a), itemHash({ ...a }));
  assert.notEqual(itemHash(a), itemHash({ ...a, monthlyCents: a.monthlyCents + 1 }));
});

test("endpoint routing per subsidiary + read-only guard", async () => {
  assert.equal(apiHostFor("WE"), "https://ca.api.ovh.com/1.0");
  assert.equal(apiHostFor("US"), "https://api.us.ovhcloud.com/1.0");
  assert.equal(apiHostFor("FR"), "https://eu.api.ovh.com/1.0");
  assert.equal(catalogUrl("eco", "WE"), "https://ca.api.ovh.com/1.0/order/catalog/public/eco?ovhSubsidiary=WE");
  assert.equal(availabilityUrl("US"), "https://api.us.ovhcloud.com/1.0/dedicated/server/datacenter/availabilities");
  assert.equal(feedFor("WE"), "ca");
  assert.equal(feedFor("US"), "us");
  assert.equal(feedFor("DE"), "eu");
  // publicGet refuses anything that is not one of the three public read endpoints
  await assert.rejects(publicGet("https://ca.api.ovh.com/1.0/order/cart"), /refusing/);
  await assert.rejects(publicGet("https://ca.api.ovh.com/1.0/me"), /refusing/);
  await assert.rejects(publicGet("http://ca.api.ovh.com/1.0/order/catalog/public/eco"), /refusing/);
});

test("the catalogue module only ever issues GET", () => {
  const src = readFileSync(path.resolve(__dirname, "../lib/dedicated/ovh-catalog.ts"), "utf8");
  const sync = readFileSync(path.resolve(__dirname, "../lib/dedicated/sync.ts"), "utf8");
  assert.match(src, /method: "GET"/);
  for (const s of [src, sync]) {
    assert.doesNotMatch(s, /method:\s*"(POST|PUT|DELETE|PATCH)"/);
    assert.doesNotMatch(s, /from\s+["']\.\.\/ovh["']/, "must not use the signed (authenticated) client");
  }
});

test("range fallback heuristics", () => {
  assert.equal(guessRange("24sk202", "KS-2"), "kimsufi");
  assert.equal(guessRange("24rise03", "RISE-3"), "rise");
  assert.equal(guessRange("zzz", "Mystery"), "other");
});

