import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { DEDICATED_DC_REGIONS, regionForDc, isMappedDc, allDedicatedRegionCodes, customerDedicatedRegionLabel, dcsForRegion, regionByCode } from "../lib/dedicated/regions.ts";
import { NODE_REGIONS, REGION_LABELS } from "../lib/node-regions.ts";
import { parseCatalog, parseAvailability } from "../lib/dedicated/ovh-catalog.ts";
import { containsBannedTerm } from "../lib/dedicated/customer-view.ts";

/** Upstream datacenter -> Nxeon region mapping. */
const fx = (n: string) => JSON.parse(readFileSync(path.resolve(__dirname, "fixtures/dedicated", n), "utf8"));

test("every datacenter in the recorded catalogue + stock feed is mapped", () => {
  const dcs = new Set<string>();
  for (const [f, k] of [["eco-WE.json", "eco"], ["baremetalServers-WE.json", "baremetalServers"]] as const) {
    for (const it of parseCatalog(fx(f), k).items) for (const d of it.datacenters) dcs.add(d);
  }
  for (const r of parseAvailability(fx("availability-ca.json"))) dcs.add(r.datacenter);
  const missing = [...dcs].filter((d) => !isMappedDc(d));
  assert.deepEqual(missing, [], `add to lib/dedicated/regions.ts: ${missing.join(", ")}`);
});

test("codes follow lib/node-regions.ts where the metro already exists there", () => {
  assert.equal(regionForDc("sgp").code, "sgp1");
  assert.equal(regionForDc("bhs").code, "bhs1");
  assert.equal(regionForDc("gra").code, "gra1");
  assert.equal(regionForDc("rbx").code, "rbx1");
  assert.equal(regionForDc("waw").code, "waw1");
  const ovhCodes = NODE_REGIONS.OVH as readonly string[];
  for (const r of Object.values(DEDICATED_DC_REGIONS)) {
    if (ovhCodes.includes(r.code)) assert.equal(r.label, REGION_LABELS[r.code], `${r.code} admin label matches node-regions`);
    assert.match(r.code, /^[a-z]{3}\d$/);
  }
});

test("regions we already sell are flagged; the rest are 'not sold yet'", () => {
  assert.equal(regionForDc("sgp").sold, true);
  assert.equal(regionForDc("bhs").sold, true);
  assert.equal(regionForDc("lon").sold, false);
  assert.equal(regionForDc("syd").sold, false);
});

test("an unknown upstream code never throws and is flagged as unmapped", () => {
  const r = regionForDc("mars-1");
  assert.equal(r.code, "unmapped:mars-1");
  assert.equal(r.sold, false);
  assert.equal(customerDedicatedRegionLabel("nope9"), "Other location");
});

test("customer labels are brand-safe and never expose the upstream code", () => {
  for (const [dc, r] of Object.entries(DEDICATED_DC_REGIONS)) {
    assert.equal(containsBannedTerm(r.customerLabel), false, r.customerLabel);
    assert.ok(!r.customerLabel.toLowerCase().includes(dc), `${dc} leaks into "${r.customerLabel}"`);
  }
});

test("reverse lookups", () => {
  assert.deepEqual(dcsForRegion("sgp1"), ["sgp"]);
  assert.equal(regionByCode("bom1")?.customerLabel, "India (Mumbai)");
  assert.ok(allDedicatedRegionCodes().includes("par1"));
  assert.equal(new Set(allDedicatedRegionCodes()).size, allDedicatedRegionCodes().length);
});

