import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import type { DedicatedServer } from "@prisma/client";
import { brandSafe, containsBannedTerm, toCustomerServerView, toPublicCatalogEntry } from "../lib/dedicated/customer-view.ts";
import { parseCatalog } from "../lib/dedicated/ovh-catalog.ts";
import { itemRegions, priceView, stockByDc } from "../lib/dedicated/catalog-view.ts";
import { DEFAULT_RULES, sellMonthlyCents } from "../lib/dedicated/pricing.ts";
import { sampleServer } from "../lib/dedicated/customer-data.ts";

/**
 * BRAND VOICE: Nxeon presents itself as the owner of its hardware. Customer-
 * facing dedicated-server code and output must never name (or hint at) the
 * upstream supplier or its product ranges. Two nets: the SOURCE of every
 * customer-facing file, and the real OUTPUT of the projections fed with the
 * recorded upstream catalogue.
 */
const ROOT = path.resolve(__dirname, "..");
const BANNED = /ovh|kimsufi|so\s*-?\s*you\s*-?\s*start|soyoustart|vrack|\bhgr\b/i;

function files(dir: string): string[] {
  const abs = path.join(ROOT, dir);
  const out: string[] = [];
  for (const e of readdirSync(abs)) {
    const rel = `${dir}/${e}`;
    if (statSync(path.join(ROOT, rel)).isDirectory()) out.push(...files(rel));
    else if (/\.tsx?$/.test(e)) out.push(rel);
  }
  return out;
}

const CUSTOMER_FILES = [
  ...files("components/dedicated"),
  ...files("app/(marketing)/dedicated-servers"),
  ...files("app/dashboard/dedicated"),
];

test("customer-facing dedicated components never contain supplier names", () => {
  assert.ok(CUSTOMER_FILES.length >= 7, `found ${CUSTOMER_FILES.length}`);
  const hits = CUSTOMER_FILES.filter((f) => BANNED.test(readFileSync(path.join(ROOT, f), "utf8")));
  assert.deepEqual(hits, [], `supplier name in customer-facing file(s): ${hits.join(", ")}`);
});

test("customer-facing files never import the admin-only catalogue modules", () => {
  for (const f of CUSTOMER_FILES) {
    const src = readFileSync(path.join(ROOT, f), "utf8");
    assert.doesNotMatch(src, /lib\/dedicated\/(ovh-catalog|sync|catalog-view)["']/, f);
    assert.doesNotMatch(src, /lib\/actions-dedicated["']/, `${f} imports admin actions`);
    assert.doesNotMatch(src, /providerServiceName|costMonthlyCents|planCode/, `${f} touches an admin-only field`);
  }
});

test("brandSafe strips supplier tokens and tidies the gaps", () => {
  assert.equal(brandSafe("OVH Advance server"), "Advance server");
  assert.equal(brandSafe("25Gbps vRack private bandwidth"), "25Gbps private bandwidth");
  assert.equal(brandSafe("KS-2 | Kimsufi"), "KS-2");
  assert.equal(brandSafe("So you Start box"), "box");
  assert.equal(brandSafe("AMD EPYC 4244P"), "AMD EPYC 4244P");
  assert.equal(containsBannedTerm("ns123.ip-1-2-3.eu (OVHcloud)"), true);
  assert.equal(containsBannedTerm("Singapore"), false);
});

const fx = (n: string) => JSON.parse(readFileSync(path.join(ROOT, "test/fixtures/dedicated", n), "utf8"));

test("public catalogue entries built from the REAL upstream catalogue carry no supplier identity", () => {
  const items = [...parseCatalog(fx("eco-WE.json"), "eco").items, ...parseCatalog(fx("baremetalServers-WE.json"), "baremetalServers").items];
  const avail = fx("availability-ca.json") as { planCode: string; memory: string; storage: string; datacenters: { datacenter: string; availability: string }[] }[];
  for (const it of items) {
    const rows = avail.filter((a) => a.planCode === it.planCode).flatMap((a) => a.datacenters.map((d) => ({ planCode: a.planCode, memory: a.memory, storage: a.storage, datacenter: d.datacenter, availability: d.availability })));
    const regions = itemRegions(it.datacenters, stockByDc(rows), new Set(["sgp1", "bhs1", "gra1", "fra1"]), []);
    const entry = toPublicCatalogEntry(
      { ...it, id: "x", displayName: "", options: it.options },
      priceView(it, DEFAULT_RULES),
      regions,
      (c) => sellMonthlyCents(0, DEFAULT_RULES, {}, c),
    );
    const json = JSON.stringify(entry);
    assert.doesNotMatch(json, BANNED, `${it.planCode} leaks: ${json.match(BANNED)?.[0]}`);
    assert.ok(!json.includes(it.planCode), `${it.planCode} plan code leaks`);
    assert.ok(!json.includes(it.name), `${it.name} upstream commercial name leaks`);
    for (const dc of it.datacenters) assert.ok(!entry.regions.some((r) => r.code === dc || r.label === dc), `dc ${dc} leaks`);
    assert.ok(entry.monthlyCents >= it.monthlyCents, "never sold below cost by default");
  }
});

test("customer server view drops every admin-only field", () => {
  const row = {
    id: "s1", userId: "u1", label: "My OVH box", hostname: "ns5000001.ip-51-79-1.net", catalogItemId: "c", offerId: null,
    cpu: "AMD EPYC 4244P", cores: 6, threads: 12, ramGb: 32, storage: "2x 960GB NVMe", bandwidth: "1 Gbps", region: "sgp1",
    datacenter: "sgp", providerServiceName: "ns5000001.ip-51-79-1.net", costMonthlyCents: 11800, ipv4: ["203.0.113.5"], ipv6: [],
    os: "Ubuntu 24.04", status: "ACTIVE", credentialsUser: "root", credentialsEnc: "enc:secret", credentialsDeliveredAt: new Date(),
    renewalDate: new Date(), renewalMonthlyCents: 14999, termMonths: 1, setupFeeCents: 0, invoiceIds: [], notes: "ordered via OVH manager",
    provisionedAt: new Date(), suspendedAt: null, suspendReason: null, cancelledAt: null, createdById: "a", createdAt: new Date(), updatedAt: new Date(),
  } as unknown as DedicatedServer;
  const v = toCustomerServerView(row);
  const json = JSON.stringify(v);
  assert.doesNotMatch(json, BANNED);
  for (const leak of ["ns5000001", "11800", "enc:secret", "ordered via", "\"sgp\""]) assert.ok(!json.includes(leak), `leaks ${leak}`);
  assert.equal(v.label, "My box");
  assert.equal(v.hostname, "ns5000001.ip-51-79-1.net".includes("ovh") ? null : v.hostname);
  assert.equal(v.region, "Singapore");
  assert.equal(v.credentialsReady, true);
  assert.equal(JSON.stringify(sampleServer().view).match(BANNED), null);
});

