const base = "http://localhost:3077", out = "/root/agent-notes/dedicated";
const secret = new TextEncoder().encode(process.env.AUTH_SECRET);
const tok = async (sub) => new SignJWT({ sub, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(secret);
const [adminId, itemId] = process.argv.slice(2);
const b = await chromium.launch();
const pages = [
  ["admin-catalogue", "/admin/dedicated"],
  ["admin-catalogue-sgp-instock", "/admin/dedicated?region=sgp1&inStock=1"],
  ["admin-item-detail", `/admin/dedicated/catalog/${itemId}`],
  ["admin-pricing", "/admin/dedicated/pricing"],
  ["admin-servers", "/admin/dedicated/servers"],
  ["preview-public-page", "/admin/preview/dedicated"],
  ["preview-customer-dashboard", "/admin/preview/dedicated/dashboard"],
];
for (const [w, h, tag] of [[1440, 900, "desktop"], [390, 844, "mobile"]]) {
  const ctx = await b.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: tag === "mobile" ? 2 : 1 });
  await ctx.addCookies([{ name: "nxeon_dedicated_dev", value: await tok(adminId), domain: "localhost", path: "/" }]);
  const p = await ctx.newPage();
  for (const [name, path] of pages) {
    const r = await p.goto(base + path, { waitUntil: "networkidle", timeout: 180000 });
    await p.waitForTimeout(800);
    await p.screenshot({ path: `${out}/${name}-${tag}.png`, fullPage: true });
    console.log(tag, name, r?.status(), await p.title());
  }
  // gate check: real customer routes must 404 with the flag off
  for (const path of ["/dedicated-servers", "/dashboard/dedicated", "/dashboard/dedicated/x"]) {
    const r = await p.goto(base + path, { waitUntil: "domcontentloaded" });
    console.log(tag, "GATE", path, r?.status());
  }
  await ctx.close();
}
await b.close();
EOF
sleep 20; tail -5 /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/dev.log

